INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1001, '《中华人民共和国民法典》', '第五百七十七条', '民事', '违约责任', NULL, NULL, NULL, '当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1002, '《中华人民共和国民法典》', '第五百七十八条', '民事', '预期违约', NULL, NULL, NULL, '当事人一方明确表示或者以自己的行为表明不履行合同义务的，对方可以在履行期限届满前请求其承担违约责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1003, '《中华人民共和国民法典》', '第一百七十九条', '民事', '承担民事责任的方式', NULL, NULL, NULL, '承担民事责任的方式主要有：（一）停止侵害；（二）排除妨碍；（三）消除危险；（四）返还财产；（五）恢复原状；（六）修理、重作、更换；（七）继续履行；（八）赔偿损失；（九）支付违约金；（十）消除影响、恢复名誉；（十一）赔礼道歉。法律规定惩罚性赔偿的，依照其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1004, '《中华人民共和国民法典》', '第一百八十八条', '民事', '诉讼时效', NULL, NULL, NULL, '向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。诉讼时效期间自权利人知道或者应当知道权利受到损害以及义务人之日起计算。法律另有规定的，依照其规定。但是，自权利受到损害之日起超过二十年的，人民法院不予保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1005, '《中华人民共和国劳动合同法》', '第四十七条', '劳动', '经济补偿的计算', NULL, NULL, NULL, '经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。劳动者月工资高于用人单位所在直辖市、设区的市级人民政府公布的本地区上年度职工月平均工资三倍的，向其支付经济补偿的标准按职工月平均工资三倍的数额支付，向其支付经济补偿的年限最高不超过十二年。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1006, '《中华人民共和国劳动合同法》', '第十九条', '劳动', '试用期', NULL, NULL, NULL, '劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。同一用人单位与同一劳动者只能约定一次试用期。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1007, '《中华人民共和国劳动合同法》', '第四十六条', '劳动', '应当支付经济补偿的情形', NULL, NULL, NULL, '有下列情形之一的，用人单位应当向劳动者支付经济补偿：（一）劳动者依照本法第三十八条规定解除劳动合同的；（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的；（三）用人单位依照本法第四十条规定解除劳动合同的；（四）用人单位依照本法第四十一条第一款规定解除劳动合同的；（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的；（六）依照本法第四十四条第四项、第五项规定终止劳动合同的；（七）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1008, '《中华人民共和国劳动法》', '第四十四条', '劳动', '延长工作时间的工资支付', NULL, NULL, NULL, '有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬；（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬；（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1009, '《中华人民共和国刑法》', '第二百六十四条', '刑事', '盗窃罪', NULL, NULL, NULL, '盗窃公私财物，数额较大的，或者多次盗窃、入户盗窃、携带凶器盗窃、扒窃的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1010, '《诉讼费用交纳办法》', '第十三条', '民事', '案件受理费的交纳标准', NULL, NULL, NULL, '财产案件根据诉讼请求的金额或者价额，按照下列比例分段累计交纳：不超过1万元的，每件交纳50元；超过1万元至10万元的部分，按照2.5%交纳；超过10万元至20万元的部分，按照2%交纳；超过20万元至50万元的部分，按照1.5%交纳；超过50万元至100万元的部分，按照1%交纳；超过100万元至200万元的部分，按照0.9%交纳。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1011, '《中华人民共和国消费者权益保护法》', '第五十五条', '民事', '惩罚性赔偿', NULL, NULL, NULL, '经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (1012, '《中华人民共和国民法典》', '第一千一百七十九条', '民事', '人身损害赔偿范围', NULL, NULL, NULL, '侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿辅助器具费和残疾赔偿金；造成死亡的，还应当赔偿丧葬费和死亡赔偿金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2001, '《中华人民共和国民法典》', '第一千零六十二条', '民事', '夫妻共同财产', NULL, NULL, NULL, '夫妻在婚姻关系存续期间所得的下列财产，为夫妻的共同财产，归夫妻共同所有：（一）工资、奖金、劳务报酬；（二）生产、经营、投资的收益；（三）知识产权的收益；（四）继承或者受赠的财产，但是本法第一千零六十三条第三项规定的除外；（五）其他应当归共同所有的财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2002, '《中华人民共和国民法典》', '第一千零八十七条', '民事', '离婚时共同财产的处理', NULL, NULL, NULL, '离婚时，夫妻的共同财产由双方协议处理；协议不成的，由人民法院根据财产的具体情况，按照照顾子女、女方和无过错方权益的原则判决。对夫或者妻在家庭土地承包经营中享有的权益等，应当依法予以保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2003, '《中华人民共和国民法典》', '第一千一百六十五条', '民事', '过错责任原则', NULL, NULL, NULL, '行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2004, '《中华人民共和国民法典》', '第一千一百八十八条', '民事', '监护人责任', NULL, NULL, NULL, '无民事行为能力人、限制民事行为能力人造成他人损害的，由监护人承担侵权责任。监护人尽到监护职责的，可以减轻其侵权责任。有财产的无民事行为能力人、限制民事行为能力人造成他人损害的，从本人财产中支付赔偿费用；不足部分，由监护人赔偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2005, '《中华人民共和国民法典》', '第五百八十四条', '民事', '违约损害赔偿范围', NULL, NULL, NULL, '当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2006, '《中华人民共和国民法典》', '第五百六十三条', '民事', '合同法定解除', NULL, NULL, NULL, '有下列情形之一的，当事人可以解除合同：（一）因不可抗力致使不能实现合同目的；（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务；（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行；（四）当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的；（五）法律规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2007, '《中华人民共和国民法典》', '第六百六十七条', '民事', '借款合同定义', NULL, NULL, NULL, '借款合同是借款人向贷款人借款，到期返还借款并支付利息的合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2008, '《中华人民共和国民法典》', '第六百八十条', '民事', '禁止高利放贷', NULL, NULL, NULL, '禁止高利放贷，借款的利率不得违反国家有关规定。借款合同对支付利息没有约定的，视为没有利息。借款合同对支付利息约定不明确，当事人不能达成补充协议的，按照当地或者当事人的交易方式、交易习惯、市场利率等因素确定利息；自然人之间借款的，视为没有利息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2009, '《中华人民共和国民法典》', '第四百九十六条', '民事', '格式条款', NULL, NULL, NULL, '格式条款是当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款。采用格式条款订立合同的，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提示对方注意免除或者减轻其责任等与对方有重大利害关系的条款，按照对方的要求，对该条款予以说明。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2010, '《中华人民共和国民法典》', '第一千一百七十六条', '民事', '自甘风险', NULL, NULL, NULL, '自愿参加具有一定风险的文体活动，因其他参加者的行为受到损害的，受害人不得请求其他参加者承担侵权责任；但是，其他参加者对损害的发生有故意或者重大过失的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2011, '《中华人民共和国劳动合同法》', '第八十七条', '劳动', '违法解除的赔偿金', NULL, NULL, NULL, '用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2012, '《中华人民共和国劳动合同法》', '第八十二条', '劳动', '未签书面合同的双倍工资', NULL, NULL, NULL, '用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2013, '《中华人民共和国劳动合同法》', '第三十九条', '劳动', '用人单位过错性解除', NULL, NULL, NULL, '劳动者有下列情形之一的，用人单位可以解除劳动合同：（一）在试用期间被证明不符合录用条件的；（二）严重违反用人单位的规章制度的；（三）严重失职，营私舞弊，给用人单位造成重大损害的；（四）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的；（五）因本法第二十六条第一款第一项规定的情形致使劳动合同无效的；（六）被依法追究刑事责任的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2014, '《中华人民共和国劳动合同法》', '第四十条', '劳动', '无过错性解除与代通知金', NULL, NULL, NULL, '有下列情形之一的，用人单位提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同：（一）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的；（二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的；（三）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2015, '《中华人民共和国劳动合同法》', '第十条', '劳动', '书面劳动合同的订立', NULL, NULL, NULL, '建立劳动关系，应当订立书面劳动合同。已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2016, '《中华人民共和国劳动合同法》', '第八十五条', '劳动', '拖欠劳动报酬的加付赔偿', NULL, NULL, NULL, '用人单位有下列情形之一的，由劳动行政部门责令限期支付劳动报酬、加班费或者经济补偿；劳动报酬低于当地最低工资标准的，应当支付其差额部分；逾期不支付的，责令用人单位按应付金额百分之五十以上百分之一百以下的标准向劳动者加付赔偿金：（一）未按照劳动合同的约定或者国家规定及时足额支付劳动者劳动报酬的；（二）低于当地最低工资标准支付劳动者工资的；（三）安排加班不支付加班费的；（四）解除或者终止劳动合同，未依照本法规定向劳动者支付经济补偿的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2017, '《工伤保险条例》', '第十四条', '劳动', '应当认定工伤的情形', NULL, NULL, NULL, '职工有下列情形之一的，应当认定为工伤：（一）在工作时间和工作场所内，因工作原因受到事故伤害的；（二）工作时间前后在工作场所内，从事与工作有关的预备性或者收尾性工作受到事故伤害的；（三）在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的；（四）患职业病的；（五）因工外出期间，由于工作原因受到伤害或者发生事故下落不明的；（六）在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2018, '《工伤保险条例》', '第十五条', '劳动', '视同工伤的情形', NULL, NULL, NULL, '职工有下列情形之一的，视同工伤：（一）在工作时间和工作岗位，突发疾病死亡或者在四十八小时之内经抢救无效死亡的；（二）在抢险救灾等维护国家利益、公共利益活动中受到伤害的；（三）职工原在军队服役，因战、因公负伤致残，已取得革命伤残军人证，到用人单位后旧伤复发的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2019, '《女职工劳动保护特别规定》', '第七条', '劳动', '产假天数', NULL, NULL, NULL, '女职工生育享受98天产假，其中产前可以休假15天；难产的，增加产假15天；生育多胞胎的，每多生育1个婴儿，增加产假15天。女职工怀孕未满4个月流产的，享受15天产假；怀孕满4个月流产的，享受42天产假。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2020, '《中华人民共和国劳动争议调解仲裁法》', '第二十七条', '劳动', '劳动仲裁时效', NULL, NULL, NULL, '劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021, '《中华人民共和国刑法》', '第二百三十四条', '刑事', '故意伤害罪', NULL, NULL, NULL, '故意伤害他人身体的，处三年以下有期徒刑、拘役或者管制。犯前款罪，致人重伤的，处三年以上十年以下有期徒刑；致人死亡或者以特别残忍手段致人重伤造成严重残疾的，处十年以上有期徒刑、无期徒刑或者死刑。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2022, '《中华人民共和国刑法》', '第二百六十六条', '刑事', '诈骗罪', NULL, NULL, NULL, '诈骗公私财物，数额较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2023, '《中华人民共和国刑法》', '第一百三十三条', '刑事', '交通肇事罪', NULL, NULL, NULL, '违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；因逃逸致人死亡的，处七年以上有期徒刑。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2024, '《中华人民共和国刑法》', '第二十条', '刑事', '正当防卫', NULL, NULL, NULL, '为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于正当防卫，不负刑事责任。正当防卫明显超过必要限度造成重大损害的，应当负刑事责任，但是应当减轻或者免除处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2025, '《中华人民共和国刑法》', '第六十七条', '刑事', '自首', NULL, NULL, NULL, '犯罪以后自动投案，如实供述自己的罪行的，是自首。对于自首的犯罪分子，可以从轻或者减轻处罚。其中，犯罪较轻的，可以免除处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2026, '《中华人民共和国公司法》', '第四十七条', '商事', '认缴出资期限', NULL, NULL, NULL, '有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额。全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2027, '《中华人民共和国公司法》', '第八十四条', '商事', '股权转让', NULL, NULL, NULL, '有限责任公司的股东之间可以相互转让其全部或者部分股权。股东向股东以外的人转让股权的，应当将股权转让的数量、价格、支付方式和期限等事项书面通知其他股东，其他股东在同等条件下有优先购买权。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2028, '《中华人民共和国公司法》', '第八十九条', '商事', '异议股东回购请求权', NULL, NULL, NULL, '有下列情形之一的，对股东会该项决议投反对票的股东可以请求公司按照合理的价格收购其股权：（一）公司连续五年不向股东分配利润，而公司该五年连续盈利，并且符合本法规定的分配利润条件；（二）公司合并、分立、转让主要财产；（三）公司章程规定的营业期限届满或者章程规定的其他解散事由出现，股东会会议通过决议修改章程使公司存续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2029, '《中华人民共和国民事诉讼法》', '第一百二十二条', '程序', '起诉条件', NULL, NULL, NULL, '起诉必须符合下列条件：（一）原告是与本案有直接利害关系的公民、法人和其他组织；（二）有明确的被告；（三）有具体的诉讼请求和事实、理由；（四）属于人民法院受理民事诉讼的范围和受诉人民法院管辖。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2030, '《中华人民共和国民事诉讼法》', '第六十七条', '程序', '举证责任', NULL, NULL, NULL, '当事人对自己提出的主张，有责任提供证据。当事人及其诉讼代理人因客观原因不能自行收集的证据，或者人民法院认为审理案件需要的证据，人民法院应当调查收集。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2031, '《中华人民共和国民事诉讼法》', '第二百四十六条', '程序', '申请执行期间', NULL, NULL, NULL, '申请执行的期间为二年。申请执行时效的中止、中断，适用法律有关诉讼时效中止、中断的规定。前款规定的期间，从法律文书规定履行期间的最后一日起计算；法律文书规定分期履行的，从规定的每次履行期间的最后一日起计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2032, '《中华人民共和国民法典》', '第一千零四十二条', '民事', '婚姻家庭禁止性规定', NULL, NULL, NULL, '禁止包办、买卖婚姻和其他干涉婚姻自由的行为。禁止借婚姻索取财物。禁止重婚。禁止有配偶者与他人同居。禁止家庭暴力。禁止家庭成员间的虐待和遗弃。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (2033, '《中华人民共和国民法典》', '第一千零七十六条', '民事', '协议离婚', NULL, NULL, NULL, '夫妻双方自愿离婚的，应当签订书面离婚协议，并亲自到婚姻登记机关申请离婚登记。离婚协议应当载明双方自愿离婚的意思表示和对子女抚养、财产以及债务处理等事项协商一致的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10001, '《中华人民共和国劳动法》', '第一条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第一条　为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10002, '《中华人民共和国劳动法》', '第二条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第二条　在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者，适用本法。 　　国家机关、事业组织、社会团体和与之建立劳动合同关系的劳动者，依照本法执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10003, '《中华人民共和国劳动法》', '第三条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第三条　劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。 　　劳动者应当完成劳动任务，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10004, '《中华人民共和国劳动法》', '第四条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第四条　用人单位应当依法建立和完善规章制度，保障劳动者享有劳动权利和履行劳动义务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10005, '《中华人民共和国劳动法》', '第五条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第五条　国家采取各种措施，促进劳动就业，发展职业教育，制定劳动标准，调节社会收入，完善社会保险，协调劳动关系，逐步提高劳动者的生活水平。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10006, '《中华人民共和国劳动法》', '第六条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第六条　国家提倡劳动者参加社会义务劳动，开展劳动竞赛和合理化建议活动，鼓励和保护劳动者进行科学研究、技术革新和发明创造，表彰和奖励劳动模范和先进工作者。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10007, '《中华人民共和国劳动法》', '第七条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第七条　劳动者有权依法参加和组织工会。 　　工会代表和维护劳动者的合法权益，依法独立自主地开展活动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10008, '《中华人民共和国劳动法》', '第八条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第八条　劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10009, '《中华人民共和国劳动法》', '第九条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第九条　国务院劳动行政部门主管全国劳动工作。 　　县级以上地方人民政府劳动行政部门主管本行政区域内的劳动工作。 第二章　促进就业 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10010, '《中华人民共和国劳动法》', '第十条', '劳动', NULL, NULL, '第二章 　促进就业　　', NULL, '第十条　国家通过促进经济和社会发展，创造就业条件，扩大就业机会。 　　国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。 　　国家支持劳动者自愿组织起来就业和从事个体经营实现就业。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10011, '《中华人民共和国劳动法》', '第十一条', '劳动', NULL, NULL, '第二章 　促进就业　　', NULL, '第十一条　地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10012, '《中华人民共和国劳动法》', '第十二条', '劳动', NULL, NULL, '第二章 　促进就业　　', NULL, '第十二条　劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10013, '《中华人民共和国劳动法》', '第十三条', '劳动', NULL, NULL, '第二章 　促进就业　　', NULL, '第十三条　妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10014, '《中华人民共和国劳动法》', '第十四条', '劳动', NULL, NULL, '第二章 　促进就业　　', NULL, '第十四条　残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10015, '《中华人民共和国劳动法》', '第十五条', '劳动', NULL, NULL, '第二章 　促进就业　　', NULL, '第十五条　禁止用人单位招用未满十六周岁的未成年人。 　　文艺、体育和特种工艺单位招用未满十六周岁的未成年人，必须遵守国家有关规定，并保障其接受义务教育的权利。 第三章　劳动合同和集体合同 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10016, '《中华人民共和国劳动法》', '第十六条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第十六条　劳动合同是劳动者与用人单位确立劳动关系、明确双方权利和义务的协议。 　　建立劳动关系应当订立劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10017, '《中华人民共和国劳动法》', '第十七条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第十七条　订立和变更劳动合同，应当遵循平等自愿、协商一致的原则，不得违反法律、行政法规的规定。 　　劳动合同依法订立即具有法律约束力，当事人必须履行劳动合同规定的义务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10018, '《中华人民共和国劳动法》', '第十八条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第十八条　下列劳动合同无效： 　　（一）违反法律、行政法规的劳动合同； 　　（二）采取欺诈、威胁等手段订立的劳动合同。 　　无效的劳动合同，从订立的时候起，就没有法律约束力。确认劳动合同部分无效的，如果不影响其余部分的效力，其余部分仍然有效。 　　劳动合同的无效，由劳动争议仲裁委员会或者人民法院确认。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10019, '《中华人民共和国劳动法》', '第十九条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第十九条　劳动合同应当以书面形式订立，并具备以下条款： 　　（一）劳动合同期限； 　　（二）工作内容； 　　（三）劳动保护和劳动条件； 　　（四）劳动报酬； 　　（五）劳动纪律； 　　（六）劳动合同终止的条件； 　　（七）违反劳动合同的责任。 　　劳动合同除前款规定的必备条款外，当事人可以协商约定其他内容。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10020, '《中华人民共和国劳动法》', '第二十条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十条　劳动合同的期限分为有固定期限、无固定期限和以完成一定的工作为期限。 　　劳动者在同一用人单位连续工作满十年以上，当事人双方同意续延劳动合同的，如果劳动者提出订立无固定期限的劳动合同，应当订立无固定期限的劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10021, '《中华人民共和国劳动法》', '第二十一条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十一条　劳动合同可以约定试用期。试用期最长不得超过六个月。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10022, '《中华人民共和国劳动法》', '第二十二条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十二条　劳动合同当事人可以在劳动合同中约定保守用人单位商业秘密的有关事项。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10023, '《中华人民共和国劳动法》', '第二十三条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十三条　劳动合同期满或者当事人约定的劳动合同终止条件出现，劳动合同即行终止。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10024, '《中华人民共和国劳动法》', '第二十四条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十四条　经劳动合同当事人协商一致，劳动合同可以解除。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10025, '《中华人民共和国劳动法》', '第二十五条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十五条　劳动者有下列情形之一的，用人单位可以解除劳动合同： 　　（一）在试用期间被证明不符合录用条件的； 　　（二）严重违反劳动纪律或者用人单位规章制度的； 　　（三）严重失职，营私舞弊，对用人单位利益造成重大损害的； 　　（四）被依法追究刑事责任的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10026, '《中华人民共和国劳动法》', '第二十六条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十六条　有下列情形之一的，用人单位可以解除劳动合同，但是应当提前三十日以书面形式通知劳动者本人： 　　（一）劳动者患病或者非因工负伤，医疗期满后，不能从事原工作也不能从事由用人单位另行安排的工作的； 　　（二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； 　　（三）劳动合同订立时所依据的客观情况发生重大变化，致使原劳动合同无法履行，经当事人协商不能就变更劳动合同达成协议的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10027, '《中华人民共和国劳动法》', '第二十七条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十七条　用人单位濒临破产进行法定整顿期间或者生产经营状况发生严重困难，确需裁减人员的，应当提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见，经向劳动行政部门报告后，可以裁减人员。 　　用人单位依据本条规定裁减人员，在六个月内录用人员的，应当优先录用被裁减的人员。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10028, '《中华人民共和国劳动法》', '第二十八条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十八条　用人单位依据本法第二十四条、第二十六条、第二十七条的规定解除劳动合同的，应当依照国家有关规定给予经济补偿。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10029, '《中华人民共和国劳动法》', '第二十九条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十九条　劳动者有下列情形之一的，用人单位不得依据本法第二十六条、第二十七条的规定解除劳动合同： 　　（一）患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； 　　（二）患病或者负伤，在规定的医疗期内的； 　　（三）女职工在孕期、产期、哺乳期内的； 　　（四）法律、行政法规规定的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10030, '《中华人民共和国劳动法》', '第三十条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十条　用人单位解除劳动合同，工会认为不适当的，有权提出意见。如果用人单位违反法律、法规或者劳动合同，工会有权要求重新处理；劳动者申请仲裁或者提起诉讼的，工会应当依法给予支持和帮助。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10031, '《中华人民共和国劳动法》', '第三十一条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十一条　劳动者解除劳动合同，应当提前三十日以书面形式通知用人单位。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10032, '《中华人民共和国劳动法》', '第三十二条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十二条　有下列情形之一的，劳动者可以随时通知用人单位解除劳动合同： 　　（一）在试用期内的； 　　（二）用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动的； 　　（三）用人单位未按照劳动合同约定支付劳动报酬或者提供劳动条件的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10033, '《中华人民共和国劳动法》', '第三十三条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十三条　企业职工一方与企业可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项，签订集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。 　　集体合同由工会代表职工与企业签订；没有建立工会的企业，由职工推举的代表与企业签订。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10034, '《中华人民共和国劳动法》', '第三十四条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十四条　集体合同签订后应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10035, '《中华人民共和国劳动法》', '第三十五条', '劳动', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十五条　依法签订的集体合同对企业和企业全体职工具有约束力。职工个人与企业订立的劳动合同中劳动条件和劳动报酬等标准不得低于集体合同的规定。 第四章　工作时间和休息休假 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10036, '《中华人民共和国劳动法》', '第三十六条', '劳动', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第三十六条　国家实行劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时的工时制度。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10037, '《中华人民共和国劳动法》', '第三十七条', '劳动', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第三十七条　对实行计件工作的劳动者，用人单位应当根据本法第三十六条规定的工时制度合理确定其劳动定额和计件报酬标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10038, '《中华人民共和国劳动法》', '第三十八条', '劳动', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第三十八条　用人单位应当保证劳动者每周至少休息一日。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10039, '《中华人民共和国劳动法》', '第三十九条', '劳动', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第三十九条　企业因生产特点不能实行本法第三十六条、第三十八条规定的，经劳动行政部门批准，可以实行其他工作和休息办法。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10040, '《中华人民共和国劳动法》', '第四十条', '劳动', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十条　用人单位在下列节日期间应当依法安排劳动者休假： 　　（一）元旦； 　　（二）春节； 　　（三）国际劳动节； 　　（四）国庆节； 　　（五）法律、法规规定的其他休假节日。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10041, '《中华人民共和国劳动法》', '第四十一条', '劳动', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十一条　用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10042, '《中华人民共和国劳动法》', '第四十二条', '劳动', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十二条　有下列情形之一的，延长工作时间不受本法第四十一条规定的限制： 　　（一）发生自然灾害、事故或者因其他原因，威胁劳动者生命健康和财产安全，需要紧急处理的； 　　（二）生产设备、交通运输线路、公共设施发生故障，影响生产和公众利益，必须及时抢修的； 　　（三）法律、行政法规规定的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10043, '《中华人民共和国劳动法》', '第四十三条', '劳动', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十三条　用人单位不得违反本法规定延长劳动者的工作时间。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10044, '《中华人民共和国劳动法》', '第四十四条', '劳动', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十四条　有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬： 　　（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬； 　　（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬； 　　（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10045, '《中华人民共和国劳动法》', '第四十五条', '劳动', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十五条　国家实行带薪年休假制度。 　　劳动者连续工作一年以上的，享受带薪年休假。具体办法由国务院规定。 第五章　工资 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10046, '《中华人民共和国劳动法》', '第四十六条', '劳动', NULL, NULL, '第五章 　工资　　', NULL, '第四十六条　工资分配应当遵循按劳分配原则，实行同工同酬。 　　工资水平在经济发展的基础上逐步提高。国家对工资总量实行宏观调控。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10047, '《中华人民共和国劳动法》', '第四十七条', '劳动', NULL, NULL, '第五章 　工资　　', NULL, '第四十七条　用人单位根据本单位的生产经营特点和经济效益，依法自主确定本单位的工资分配方式和工资水平。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10048, '《中华人民共和国劳动法》', '第四十八条', '劳动', NULL, NULL, '第五章 　工资　　', NULL, '第四十八条　国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。 　　用人单位支付劳动者的工资不得低于当地最低工资标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10049, '《中华人民共和国劳动法》', '第四十九条', '劳动', NULL, NULL, '第五章 　工资　　', NULL, '第四十九条　确定和调整最低工资标准应当综合参考下列因素： 　　（一）劳动者本人及平均赡养人口的最低生活费用； 　　（二）社会平均工资水平； 　　（三）劳动生产率； 　　（四）就业状况； 　　（五）地区之间经济发展水平的差异。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10050, '《中华人民共和国劳动法》', '第五十条', '劳动', NULL, NULL, '第五章 　工资　　', NULL, '第五十条　工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10051, '《中华人民共和国劳动法》', '第五十一条', '劳动', NULL, NULL, '第五章 　工资　　', NULL, '第五十一条　劳动者在法定休假日和婚丧假期间以及依法参加社会活动期间，用人单位应当依法支付工资。 第六章　劳动安全卫生 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10052, '《中华人民共和国劳动法》', '第五十二条', '劳动', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十二条　用人单位必须建立、健全劳动安全卫生制度，严格执行国家劳动安全卫生规程和标准，对劳动者进行劳动安全卫生教育，防止劳动过程中的事故，减少职业危害。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10053, '《中华人民共和国劳动法》', '第五十三条', '劳动', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十三条　劳动安全卫生设施必须符合国家规定的标准。 　　新建、改建、扩建工程的劳动安全卫生设施必须与主体工程同时设计、同时施工、同时投入生产和使用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10054, '《中华人民共和国劳动法》', '第五十四条', '劳动', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十四条　用人单位必须为劳动者提供符合国家规定的劳动安全卫生条件和必要的劳动防护用品，对从事有职业危害作业的劳动者应当定期进行健康检查。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10055, '《中华人民共和国劳动法》', '第五十五条', '劳动', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十五条　从事特种作业的劳动者必须经过专门培训并取得特种作业资格。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10056, '《中华人民共和国劳动法》', '第五十六条', '劳动', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十六条　劳动者在劳动过程中必须严格遵守安全操作规程。 　　劳动者对用人单位管理人员违章指挥、强令冒险作业，有权拒绝执行；对危害生命安全和身体健康的行为，有权提出批评、检举和控告。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10057, '《中华人民共和国劳动法》', '第五十七条', '劳动', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十七条　国家建立伤亡事故和职业病统计报告和处理制度。县级以上各级人民政府劳动行政部门、有关部门和用人单位应当依法对劳动者在劳动过程中发生的伤亡事故和劳动者的职业病状况，进行统计、报告和处理。 第七章　女职工和未成年工特殊保护 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10058, '《中华人民共和国劳动法》', '第五十八条', '劳动', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第五十八条　国家对女职工和未成年工实行特殊劳动保护。 　　未成年工是指年满十六周岁未满十八周岁的劳动者。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10059, '《中华人民共和国劳动法》', '第五十九条', '劳动', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第五十九条　禁止安排女职工从事矿山井下、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10060, '《中华人民共和国劳动法》', '第六十条', '劳动', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十条　不得安排女职工在经期从事高处、低温、冷水作业和国家规定的第三级体力劳动强度的劳动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10061, '《中华人民共和国劳动法》', '第六十一条', '劳动', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十一条　不得安排女职工在怀孕期间从事国家规定的第三级体力劳动强度的劳动和孕期禁忌从事的劳动。对怀孕七个月以上的女职工，不得安排其延长工作时间和夜班劳动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10062, '《中华人民共和国劳动法》', '第六十二条', '劳动', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十二条　女职工生育享受不少于九十天的产假。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10063, '《中华人民共和国劳动法》', '第六十三条', '劳动', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十三条　不得安排女职工在哺乳未满一周岁的婴儿期间从事国家规定的第三级体力劳动强度的劳动和哺乳期禁忌从事的其他劳动，不得安排其延长工作时间和夜班劳动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10064, '《中华人民共和国劳动法》', '第六十四条', '劳动', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十四条　不得安排未成年工从事矿山井下、有毒有害、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10065, '《中华人民共和国劳动法》', '第六十五条', '劳动', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十五条　用人单位应当对未成年工定期进行健康检查。 第八章　职业培训 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10066, '《中华人民共和国劳动法》', '第六十六条', '劳动', NULL, NULL, '第八章 　职业培训　　', NULL, '第六十六条　国家通过各种途径，采取各种措施，发展职业培训事业，开发劳动者的职业技能，提高劳动者素质，增强劳动者的就业能力和工作能力。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10067, '《中华人民共和国劳动法》', '第六十七条', '劳动', NULL, NULL, '第八章 　职业培训　　', NULL, '第六十七条　各级人民政府应当把发展职业培训纳入社会经济发展的规划，鼓励和支持有条件的企业、事业组织、社会团体和个人进行各种形式的职业培训。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10068, '《中华人民共和国劳动法》', '第六十八条', '劳动', NULL, NULL, '第八章 　职业培训　　', NULL, '第六十八条　用人单位应当建立职业培训制度，按照国家规定提取和使用职业培训经费，根据本单位实际，有计划地对劳动者进行职业培训。 　　从事技术工种的劳动者，上岗前必须经过培训。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10069, '《中华人民共和国劳动法》', '第六十九条', '劳动', NULL, NULL, '第八章 　职业培训　　', NULL, '第六十九条　国家确定职业分类，对规定的职业制定职业技能标准，实行职业资格证书制度，由经备案的考核鉴定机构负责对劳动者实施职业技能考核鉴定。 第九章　社会保险和福利 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10070, '《中华人民共和国劳动法》', '第七十条', '劳动', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十条　国家发展社会保险事业，建立社会保险制度，设立社会保险基金，使劳动者在年老、患病、工伤、失业、生育等情况下获得帮助和补偿。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10071, '《中华人民共和国劳动法》', '第七十一条', '劳动', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十一条　社会保险水平应当与社会经济发展水平和社会承受能力相适应。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10072, '《中华人民共和国劳动法》', '第七十二条', '劳动', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十二条　社会保险基金按照保险类型确定资金来源，逐步实行社会统筹。用人单位和劳动者必须依法参加社会保险，缴纳社会保险费。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10073, '《中华人民共和国劳动法》', '第七十三条', '劳动', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十三条　劳动者在下列情形下，依法享受社会保险待遇： 　　（一）退休； 　　（二）患病、负伤； 　　（三）因工伤残或者患职业病； 　　（四）失业； 　　（五）生育。 　　劳动者死亡后，其遗属依法享受遗属津贴。 　　劳动者享受社会保险待遇的条件和标准由法律、法规规定。 　　劳动者享受的社会保险金必须按时足额支付。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10074, '《中华人民共和国劳动法》', '第七十四条', '劳动', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十四条　社会保险基金经办机构依照法律规定收支、管理和运营社会保险基金，并负有使社会保险基金保值增值的责任。 　　社会保险基金监督机构依照法律规定，对社会保险基金的收支、管理和运营实施监督。 　　社会保险基金经办机构和社会保险基金监督机构的设立和职能由法律规定。 　　任何组织和个人不得挪用社会保险基金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10075, '《中华人民共和国劳动法》', '第七十五条', '劳动', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十五条　国家鼓励用人单位根据本单位实际情况为劳动者建立补充保险。 　　国家提倡劳动者个人进行储蓄性保险。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10076, '《中华人民共和国劳动法》', '第七十六条', '劳动', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十六条　国家发展社会福利事业，兴建公共福利设施，为劳动者休息、休养和疗养提供条件。 　　用人单位应当创造条件，改善集体福利，提高劳动者的福利待遇。 第十章　劳动争议 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10077, '《中华人民共和国劳动法》', '第七十七条', '劳动', NULL, NULL, '第十章 　劳动争议　　', NULL, '第七十七条　用人单位与劳动者发生劳动争议，当事人可以依法申请调解、仲裁、提起诉讼，也可以协商解决。 　　调解原则适用于仲裁和诉讼程序。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10078, '《中华人民共和国劳动法》', '第七十八条', '劳动', NULL, NULL, '第十章 　劳动争议　　', NULL, '第七十八条　解决劳动争议，应当根据合法、公正、及时处理的原则，依法维护劳动争议当事人的合法权益。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10079, '《中华人民共和国劳动法》', '第七十九条', '劳动', NULL, NULL, '第十章 　劳动争议　　', NULL, '第七十九条　劳动争议发生后，当事人可以向本单位劳动争议调解委员会申请调解；调解不成，当事人一方要求仲裁的，可以向劳动争议仲裁委员会申请仲裁。当事人一方也可以直接向劳动争议仲裁委员会申请仲裁。对仲裁裁决不服的，可以向人民法院提起诉讼。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10080, '《中华人民共和国劳动法》', '第八十条', '劳动', NULL, NULL, '第十章 　劳动争议　　', NULL, '第八十条　在用人单位内，可以设立劳动争议调解委员会。劳动争议调解委员会由职工代表、用人单位代表和工会代表组成。劳动争议调解委员会主任由工会代表担任。 　　劳动争议经调解达成协议的，当事人应当履行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10081, '《中华人民共和国劳动法》', '第八十一条', '劳动', NULL, NULL, '第十章 　劳动争议　　', NULL, '第八十一条　劳动争议仲裁委员会由劳动行政部门代表、同级工会代表、用人单位方面的代表组成。劳动争议仲裁委员会主任由劳动行政部门代表担任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10082, '《中华人民共和国劳动法》', '第八十二条', '劳动', NULL, NULL, '第十章 　劳动争议　　', NULL, '第八十二条　提出仲裁要求的一方应当自劳动争议发生之日起六十日内向劳动争议仲裁委员会提出书面申请。仲裁裁决一般应在收到仲裁申请的六十日内作出。对仲裁裁决无异议的，当事人必须履行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10083, '《中华人民共和国劳动法》', '第八十三条', '劳动', NULL, NULL, '第十章 　劳动争议　　', NULL, '第八十三条　劳动争议当事人对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。一方当事人在法定期限内不起诉又不履行仲裁裁决的，另一方当事人可以申请人民法院强制执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10084, '《中华人民共和国劳动法》', '第八十四条', '劳动', NULL, NULL, '第十章 　劳动争议　　', NULL, '第八十四条　因签订集体合同发生争议，当事人协商解决不成的，当地人民政府劳动行政部门可以组织有关各方协调处理。 　　因履行集体合同发生争议，当事人协商解决不成的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。 第十一章　监督检查 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10085, '《中华人民共和国劳动法》', '第八十五条', '劳动', NULL, NULL, '第十一章 　监督检查　　', NULL, '第八十五条　县级以上各级人民政府劳动行政部门依法对用人单位遵守劳动法律、法规的情况进行监督检查，对违反劳动法律、法规的行为有权制止，并责令改正。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10086, '《中华人民共和国劳动法》', '第八十六条', '劳动', NULL, NULL, '第十一章 　监督检查　　', NULL, '第八十六条　县级以上各级人民政府劳动行政部门监督检查人员执行公务，有权进入用人单位了解执行劳动法律、法规的情况，查阅必要的资料，并对劳动场所进行检查。 　　县级以上各级人民政府劳动行政部门监督检查人员执行公务，必须出示证件，秉公执法并遵守有关规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10087, '《中华人民共和国劳动法》', '第八十七条', '劳动', NULL, NULL, '第十一章 　监督检查　　', NULL, '第八十七条　县级以上各级人民政府有关部门在各自职责范围内，对用人单位遵守劳动法律、法规的情况进行监督。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10088, '《中华人民共和国劳动法》', '第八十八条', '劳动', NULL, NULL, '第十一章 　监督检查　　', NULL, '第八十八条　各级工会依法维护劳动者的合法权益，对用人单位遵守劳动法律、法规的情况进行监督。 　　任何组织和个人对于违反劳动法律、法规的行为有权检举和控告。 第十二章　法律责任 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10089, '《中华人民共和国劳动法》', '第八十九条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第八十九条　用人单位制定的劳动规章制度违反法律、法规规定的，由劳动行政部门给予警告，责令改正；对劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10090, '《中华人民共和国劳动法》', '第九十条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十条　用人单位违反本法规定，延长劳动者工作时间的，由劳动行政部门给予警告，责令改正，并可以处以罚款。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10091, '《中华人民共和国劳动法》', '第九十一条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十一条　用人单位有下列侵害劳动者合法权益情形之一的，由劳动行政部门责令支付劳动者的工资报酬、经济补偿，并可以责令支付赔偿金： 　　（一）克扣或者无故拖欠劳动者工资的； 　　（二）拒不支付劳动者延长工作时间工资报酬的； 　　（三）低于当地最低工资标准支付劳动者工资的； 　　（四）解除劳动合同后，未依照本法规定给予劳动者经济补偿的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10092, '《中华人民共和国劳动法》', '第九十二条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十二条　用人单位的劳动安全设施和劳动卫生条件不符合国家规定或者未向劳动者提供必要的劳动防护用品和劳动保护设施的，由劳动行政部门或者有关部门责令改正，可以处以罚款；情节严重的，提请县级以上人民政府决定责令停产整顿；对事故隐患不采取措施，致使发生重大事故，造成劳动者生命和财产损失的，对责任人员依照刑法有关规定追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10093, '《中华人民共和国劳动法》', '第九十三条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十三条　用人单位强令劳动者违章冒险作业，发生重大伤亡事故，造成严重后果的，对责任人员依法追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10094, '《中华人民共和国劳动法》', '第九十四条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十四条　用人单位非法招用未满十六周岁的未成年人的，由劳动行政部门责令改正，处以罚款；情节严重的，由市场监督管理部门吊销营业执照。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10095, '《中华人民共和国劳动法》', '第九十五条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十五条　用人单位违反本法对女职工和未成年工的保护规定，侵害其合法权益的，由劳动行政部门责令改正，处以罚款；对女职工或者未成年工造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10096, '《中华人民共和国劳动法》', '第九十六条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十六条　用人单位有下列行为之一，由公安机关对责任人员处以十五日以下拘留、罚款或者警告；构成犯罪的，对责任人员依法追究刑事责任： 　　（一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的； 　　（二）侮辱、体罚、殴打、非法搜查和拘禁劳动者的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10097, '《中华人民共和国劳动法》', '第九十七条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十七条　由于用人单位的原因订立的无效合同，对劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10098, '《中华人民共和国劳动法》', '第九十八条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十八条　用人单位违反本法规定的条件解除劳动合同或者故意拖延不订立劳动合同的，由劳动行政部门责令改正；对劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10099, '《中华人民共和国劳动法》', '第九十九条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十九条　用人单位招用尚未解除劳动合同的劳动者，对原用人单位造成经济损失的，该用人单位应当依法承担连带赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10100, '《中华人民共和国劳动法》', '第一百条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百条　用人单位无故不缴纳社会保险费的，由劳动行政部门责令其限期缴纳；逾期不缴的，可以加收滞纳金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10101, '《中华人民共和国劳动法》', '第一百零一条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百零一条　用人单位无理阻挠劳动行政部门、有关部门及其工作人员行使监督检查权，打击报复举报人员的，由劳动行政部门或者有关部门处以罚款；构成犯罪的，对责任人员依法追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10102, '《中华人民共和国劳动法》', '第一百零二条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百零二条　劳动者违反本法规定的条件解除劳动合同或者违反劳动合同中约定的保密事项，对用人单位造成经济损失的，应当依法承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10103, '《中华人民共和国劳动法》', '第一百零三条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百零三条　劳动行政部门或者有关部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10104, '《中华人民共和国劳动法》', '第一百零四条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百零四条　国家工作人员和社会保险基金经办机构的工作人员挪用社会保险基金，构成犯罪的，依法追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10105, '《中华人民共和国劳动法》', '第一百零五条', '劳动', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百零五条　违反本法规定侵害劳动者合法权益，其他法律、行政法规已规定处罚的，依照该法律、行政法规的规定处罚。 第十三章　附则 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10106, '《中华人民共和国劳动法》', '第一百零六条', '劳动', NULL, NULL, '第十三章 　附则　　', NULL, '第一百零六条　省、自治区、直辖市人民政府根据本法和本地区的实际情况，规定劳动合同制度的实施步骤，报国务院备案。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10107, '《中华人民共和国劳动法》', '第一百零七条', '劳动', NULL, NULL, '第十三章 　附则　　', NULL, '第一百零七条　本法自1995年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10201, '《中华人民共和国劳动合同法》', '第一条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第一条　为了完善劳动合同制度，明确劳动合同双方当事人的权利和义务，保护劳动者的合法权益，构建和发展和谐稳定的劳动关系，制定本法。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10202, '《中华人民共和国劳动合同法》', '第二条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第二条　中华人民共和国境内的企业、个体经济组织、民办非企业单位等组织（以下称用人单位）与劳动者建立劳动关系，订立、履行、变更、解除或者终止劳动合同，适用本法。 　　国家机关、事业单位、社会团体和与其建立劳动关系的劳动者，订立、履行、变更、解除或者终止劳动合同，依照本法执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10203, '《中华人民共和国劳动合同法》', '第三条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第三条　订立劳动合同，应当遵循合法、公平、平等自愿、协商一致、诚实信用的原则。 　　依法订立的劳动合同具有约束力，用人单位与劳动者应当履行劳动合同约定的义务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10204, '《中华人民共和国劳动合同法》', '第四条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第四条　用人单位应当依法建立和完善劳动规章制度，保障劳动者享有劳动权利、履行劳动义务。 　　用人单位在制定、修改或者决定有关劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利、职工培训、劳动纪律以及劳动定额管理等直接涉及劳动者切身利益的规章制度或者重大事项时，应当经职工代表大会或者全体职工讨论，提出方案和意见，与工会或者职工代表平等协商确定。 　　在规章制度和重大事项决定实施过程中，工会或者职工认为不适当的，有权向用人单位提出，通过协商予以修改完善。 　　用人单位应当将直接涉及劳动者切身利益的规章制度和重大事项决定公示，或者告知劳动者。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10205, '《中华人民共和国劳动合同法》', '第五条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第五条　县级以上人民政府劳动行政部门会同工会和企业方面代表，建立健全协调劳动关系三方机制，共同研究解决有关劳动关系的重大问题。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10206, '《中华人民共和国劳动合同法》', '第六条', '劳动', NULL, NULL, '第一章 　总则　　', NULL, '第六条　工会应当帮助、指导劳动者与用人单位依法订立和履行劳动合同，并与用人单位建立集体协商机制，维护劳动者的合法权益。 第二章　劳动合同的订立 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10207, '《中华人民共和国劳动合同法》', '第七条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第七条　用人单位自用工之日起即与劳动者建立劳动关系。用人单位应当建立职工名册备查。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10208, '《中华人民共和国劳动合同法》', '第八条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第八条　用人单位招用劳动者时，应当如实告知劳动者工作内容、工作条件、工作地点、职业危害、安全生产状况、劳动报酬，以及劳动者要求了解的其他情况；用人单位有权了解劳动者与劳动合同直接相关的基本情况，劳动者应当如实说明。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10209, '《中华人民共和国劳动合同法》', '第九条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第九条　用人单位招用劳动者，不得扣押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10210, '《中华人民共和国劳动合同法》', '第十条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十条　建立劳动关系，应当订立书面劳动合同。 　　已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。 　　用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10211, '《中华人民共和国劳动合同法》', '第十一条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十一条　用人单位未在用工的同时订立书面劳动合同，与劳动者约定的劳动报酬不明确的，新招用的劳动者的劳动报酬按照集体合同规定的标准执行；没有集体合同或者集体合同未规定的，实行同工同酬。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10212, '《中华人民共和国劳动合同法》', '第十二条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十二条　劳动合同分为固定期限劳动合同、无固定期限劳动合同和以完成一定工作任务为期限的劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10213, '《中华人民共和国劳动合同法》', '第十三条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十三条　固定期限劳动合同，是指用人单位与劳动者约定合同终止时间的劳动合同。 　　用人单位与劳动者协商一致，可以订立固定期限劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10214, '《中华人民共和国劳动合同法》', '第十四条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十四条　无固定期限劳动合同，是指用人单位与劳动者约定无确定终止时间的劳动合同。 　　用人单位与劳动者协商一致，可以订立无固定期限劳动合同。有下列情形之一，劳动者提出或者同意续订、订立劳动合同的，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同: 　　（一）劳动者在该用人单位连续工作满十年的； 　　（二）用人单位初次实行劳动合同制度或者国有企业改制重新订立劳动合同时，劳动者在该用人单位连续工作满十年且距法定退休年龄不足十年的； 　　（三）连续订立二次固定期限劳动合同，且劳动者没有本法第三十九条和第四十条第一项、第二项规定的情形，续订劳动合同的。 　　用人单位自用工之日起满一年不与劳动者订立书面劳动合同的，视为用人单位与劳动者已订立无固定期限劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10215, '《中华人民共和国劳动合同法》', '第十五条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十五条　以完成一定工作任务为期限的劳动合同，是指用人单位与劳动者约定以某项工作的完成为合同期限的劳动合同。 　　用人单位与劳动者协商一致，可以订立以完成一定工作任务为期限的劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10216, '《中华人民共和国劳动合同法》', '第十六条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十六条　劳动合同由用人单位与劳动者协商一致，并经用人单位与劳动者在劳动合同文本上签字或者盖章生效。 　　劳动合同文本由用人单位和劳动者各执一份。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10217, '《中华人民共和国劳动合同法》', '第十七条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十七条　劳动合同应当具备以下条款: 　　（一）用人单位的名称、住所和法定代表人或者主要负责人； 　　（二）劳动者的姓名、住址和居民身份证或者其他有效身份证件号码； 　　（三）劳动合同期限； 　　（四）工作内容和工作地点； 　　（五）工作时间和休息休假； 　　（六）劳动报酬； 　　（七）社会保险； 　　（八）劳动保护、劳动条件和职业危害防护； 　　（九）法律、法规规定应当纳入劳动合同的其他事项。 　　劳动合同除前款规定的必备条款外，用人单位与劳动者可以约定试用期、培训、保守秘密、补充保险和福利待遇等其他事项。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10218, '《中华人民共和国劳动合同法》', '第十八条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十八条　劳动合同对劳动报酬和劳动条件等标准约定不明确，引发争议的，用人单位与劳动者可以重新协商；协商不成的，适用集体合同规定；没有集体合同或者集体合同未规定劳动报酬的，实行同工同酬；没有集体合同或者集体合同未规定劳动条件等标准的，适用国家有关规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10219, '《中华人民共和国劳动合同法》', '第十九条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十九条　劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。 　　同一用人单位与同一劳动者只能约定一次试用期。 　　以完成一定工作任务为期限的劳动合同或者劳动合同期限不满三个月的，不得约定试用期。 　　试用期包含在劳动合同期限内。劳动合同仅约定试用期的，试用期不成立，该期限为劳动合同期限。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10220, '《中华人民共和国劳动合同法》', '第二十条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十条　劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10221, '《中华人民共和国劳动合同法》', '第二十一条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十一条　在试用期中，除劳动者有本法第三十九条和第四十条第一项、第二项规定的情形外，用人单位不得解除劳动合同。用人单位在试用期解除劳动合同的，应当向劳动者说明理由。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10222, '《中华人民共和国劳动合同法》', '第二十二条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十二条　用人单位为劳动者提供专项培训费用，对其进行专业技术培训的，可以与该劳动者订立协议，约定服务期。 　　劳动者违反服务期约定的，应当按照约定向用人单位支付违约金。违约金的数额不得超过用人单位提供的培训费用。用人单位要求劳动者支付的违约金不得超过服务期尚未履行部分所应分摊的培训费用。 　　用人单位与劳动者约定服务期的，不影响按照正常的工资调整机制提高劳动者在服务期期间的劳动报酬。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10223, '《中华人民共和国劳动合同法》', '第二十三条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十三条　用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。 　　对负有保密义务的劳动者，用人单位可以在劳动合同或者保密协议中与劳动者约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予劳动者经济补偿。劳动者违反竞业限制约定的，应当按照约定向用人单位支付违约金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10224, '《中华人民共和国劳动合同法》', '第二十四条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十四条　竞业限制的人员限于用人单位的高级管理人员、高级技术人员和其他负有保密义务的人员。竞业限制的范围、地域、期限由用人单位与劳动者约定，竞业限制的约定不得违反法律、法规的规定。 　　在解除或者终止劳动合同后，前款规定的人员到与本单位生产或者经营同类产品、从事同类业务的有竞争关系的其他用人单位，或者自己开业生产或者经营同类产品、从事同类业务的竞业限制期限，不得超过二年。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10225, '《中华人民共和国劳动合同法》', '第二十五条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十五条　除本法第二十二条和第二十三条规定的情形外，用人单位不得与劳动者约定由劳动者承担违约金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10226, '《中华人民共和国劳动合同法》', '第二十六条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十六条　下列劳动合同无效或者部分无效: 　　（一）以欺诈、胁迫的手段或者乘人之危，使对方在违背真实意思的情况下订立或者变更劳动合同的； 　　（二）用人单位免除自己的法定责任、排除劳动者权利的； 　　（三）违反法律、行政法规强制性规定的。 　　对劳动合同的无效或者部分无效有争议的，由劳动争议仲裁机构或者人民法院确认。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10227, '《中华人民共和国劳动合同法》', '第二十七条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十七条　劳动合同部分无效，不影响其他部分效力的，其他部分仍然有效。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10228, '《中华人民共和国劳动合同法》', '第二十八条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十八条　劳动合同被确认无效，劳动者已付出劳动的，用人单位应当向劳动者支付劳动报酬。劳动报酬的数额，参照本单位相同或者相近岗位劳动者的劳动报酬确定。 第三章　劳动合同的履行和变更 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10229, '《中华人民共和国劳动合同法》', '第二十九条', '劳动', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第二十九条　用人单位与劳动者应当按照劳动合同的约定，全面履行各自的义务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10230, '《中华人民共和国劳动合同法》', '第三十条', '劳动', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十条　用人单位应当按照劳动合同约定和国家规定，向劳动者及时足额支付劳动报酬。 　　用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向当地人民法院申请支付令，人民法院应当依法发出支付令。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10231, '《中华人民共和国劳动合同法》', '第三十一条', '劳动', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十一条　用人单位应当严格执行劳动定额标准，不得强迫或者变相强迫劳动者加班。用人单位安排加班的，应当按照国家有关规定向劳动者支付加班费。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10232, '《中华人民共和国劳动合同法》', '第三十二条', '劳动', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十二条　劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，不视为违反劳动合同。 　　劳动者对危害生命安全和身体健康的劳动条件，有权对用人单位提出批评、检举和控告。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10233, '《中华人民共和国劳动合同法》', '第三十三条', '劳动', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十三条　用人单位变更名称、法定代表人、主要负责人或者投资人等事项，不影响劳动合同的履行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10234, '《中华人民共和国劳动合同法》', '第三十四条', '劳动', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十四条　用人单位发生合并或者分立等情况，原劳动合同继续有效，劳动合同由承继其权利和义务的用人单位继续履行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10235, '《中华人民共和国劳动合同法》', '第三十五条', '劳动', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十五条　用人单位与劳动者协商一致，可以变更劳动合同约定的内容。变更劳动合同，应当采用书面形式。 　　变更后的劳动合同文本由用人单位和劳动者各执一份。 第四章　劳动合同的解除和终止 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10236, '《中华人民共和国劳动合同法》', '第三十六条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第三十六条　用人单位与劳动者协商一致，可以解除劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10237, '《中华人民共和国劳动合同法》', '第三十七条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第三十七条　劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同。劳动者在试用期内提前三日通知用人单位，可以解除劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10238, '《中华人民共和国劳动合同法》', '第三十八条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第三十八条　用人单位有下列情形之一的，劳动者可以解除劳动合同: 　　（一）未按照劳动合同约定提供劳动保护或者劳动条件的； 　　（二）未及时足额支付劳动报酬的； 　　（三）未依法为劳动者缴纳社会保险费的； 　　（四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的； 　　（五）因本法第二十六条第一款规定的情形致使劳动合同无效的； 　　（六）法律、行政法规规定劳动者可以解除劳动合同的其他情形。 　　用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的，或者用人单位违章指挥、强令冒险作业危及劳动者人身安全的，劳动者可以立即解除劳动合同，不需事先告知用人单位。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10239, '《中华人民共和国劳动合同法》', '第三十九条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第三十九条　劳动者有下列情形之一的，用人单位可以解除劳动合同: 　　（一）在试用期间被证明不符合录用条件的； 　　（二）严重违反用人单位的规章制度的； 　　（三）严重失职，营私舞弊，给用人单位造成重大损害的； 　　（四）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； 　　（五）因本法第二十六条第一款第一项规定的情形致使劳动合同无效的； 　　（六）被依法追究刑事责任的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10240, '《中华人民共和国劳动合同法》', '第四十条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十条　有下列情形之一的，用人单位提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同: 　　（一）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的； 　　（二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； 　　（三）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10241, '《中华人民共和国劳动合同法》', '第四十一条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十一条　有下列情形之一，需要裁减人员二十人以上或者裁减不足二十人但占企业职工总数百分之十以上的，用人单位提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见后，裁减人员方案经向劳动行政部门报告，可以裁减人员: 　　（一）依照企业破产法规定进行重整的； 　　（二）生产经营发生严重困难的； 　　（三）企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的； 　　（四）其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。 　　裁减人员时，应当优先留用下列人员: 　　（一）与本单位订立较长期限的固定期限劳动合同的； 　　（二）与本单位订立无固定期限劳动合同的； 　　（三）家庭无其他就业人员，有需要扶养的老人或者未成年人的。 　　用人单位依照本条第一款规定裁减人员，在六个月内重新招用人员的，应当通知被裁减的人员，并在同等条件下优先招用被裁减的人员。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10242, '《中华人民共和国劳动合同法》', '第四十二条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十二条　劳动者有下列情形之一的，用人单位不得依照本法第四十条、第四十一条的规定解除劳动合同: 　　（一）从事接触职业病危害作业的劳动者未进行离岗前职业健康检查，或者疑似职业病病人在诊断或者医学观察期间的； 　　（二）在本单位患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； 　　（三）患病或者非因工负伤，在规定的医疗期内的； 　　（四）女职工在孕期、产期、哺乳期的； 　　（五）在本单位连续工作满十五年，且距法定退休年龄不足五年的； 　　（六）法律、行政法规规定的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10243, '《中华人民共和国劳动合同法》', '第四十三条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十三条　用人单位单方解除劳动合同，应当事先将理由通知工会。用人单位违反法律、行政法规规定或者劳动合同约定的，工会有权要求用人单位纠正。用人单位应当研究工会的意见，并将处理结果书面通知工会。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10244, '《中华人民共和国劳动合同法》', '第四十四条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十四条　有下列情形之一的，劳动合同终止: 　　（一）劳动合同期满的； 　　（二）劳动者开始依法享受基本养老保险待遇的； 　　（三）劳动者死亡，或者被人民法院宣告死亡或者宣告失踪的； 　　（四）用人单位被依法宣告破产的； 　　（五）用人单位被吊销营业执照、责令关闭、撤销或者用人单位决定提前解散的； 　　（六）法律、行政法规规定的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10245, '《中华人民共和国劳动合同法》', '第四十五条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十五条　劳动合同期满，有本法第四十二条规定情形之一的，劳动合同应当续延至相应的情形消失时终止。但是，本法第四十二条第二项规定丧失或者部分丧失劳动能力劳动者的劳动合同的终止，按照国家有关工伤保险的规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10246, '《中华人民共和国劳动合同法》', '第四十六条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十六条　有下列情形之一的，用人单位应当向劳动者支付经济补偿: 　　（一）劳动者依照本法第三十八条规定解除劳动合同的； 　　（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的； 　　（三）用人单位依照本法第四十条规定解除劳动合同的； 　　（四）用人单位依照本法第四十一条第一款规定解除劳动合同的； 　　（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的； 　　（六）依照本法第四十四条第四项、第五项规定终止劳动合同的； 　　（七）法律、行政法规规定的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10247, '《中华人民共和国劳动合同法》', '第四十七条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十七条　经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。 　　劳动者月工资高于用人单位所在直辖市、设区的市级人民政府公布的本地区上年度职工月平均工资三倍的，向其支付经济补偿的标准按职工月平均工资三倍的数额支付，向其支付经济补偿的年限最高不超过十二年。 　　本条所称月工资是指劳动者在劳动合同解除或者终止前十二个月的平均工资。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10248, '《中华人民共和国劳动合同法》', '第四十八条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十八条　用人单位违反本法规定解除或者终止劳动合同，劳动者要求继续履行劳动合同的，用人单位应当继续履行；劳动者不要求继续履行劳动合同或者劳动合同已经不能继续履行的，用人单位应当依照本法第八十七条规定支付赔偿金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10249, '《中华人民共和国劳动合同法》', '第四十九条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十九条　国家采取措施，建立健全劳动者社会保险关系跨地区转移接续制度。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10250, '《中华人民共和国劳动合同法》', '第五十条', '劳动', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第五十条　用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在十五日内为劳动者办理档案和社会保险关系转移手续。 　　劳动者应当按照双方约定，办理工作交接。用人单位依照本法有关规定应当向劳动者支付经济补偿的，在办结工作交接时支付。 　　用人单位对已经解除或者终止的劳动合同的文本，至少保存二年备查。 第五章　特别规定 第一节　集体合同 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10251, '《中华人民共和国劳动合同法》', '第五十一条', '劳动', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十一条　企业职工一方与用人单位通过平等协商，可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项订立集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。 　　集体合同由工会代表企业职工一方与用人单位订立；尚未建立工会的用人单位，由上级工会指导劳动者推举的代表与用人单位订立。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10252, '《中华人民共和国劳动合同法》', '第五十二条', '劳动', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十二条　企业职工一方与用人单位可以订立劳动安全卫生、女职工权益保护、工资调整机制等专项集体合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10253, '《中华人民共和国劳动合同法》', '第五十三条', '劳动', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十三条　在县级以下区域内，建筑业、采矿业、餐饮服务业等行业可以由工会与企业方面代表订立行业性集体合同，或者订立区域性集体合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10254, '《中华人民共和国劳动合同法》', '第五十四条', '劳动', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十四条　集体合同订立后，应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。 　　依法订立的集体合同对用人单位和劳动者具有约束力。行业性、区域性集体合同对当地本行业、本区域的用人单位和劳动者具有约束力。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10255, '《中华人民共和国劳动合同法》', '第五十五条', '劳动', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十五条　集体合同中劳动报酬和劳动条件等标准不得低于当地人民政府规定的最低标准；用人单位与劳动者订立的劳动合同中劳动报酬和劳动条件等标准不得低于集体合同规定的标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10256, '《中华人民共和国劳动合同法》', '第五十六条', '劳动', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十六条　用人单位违反集体合同，侵犯职工劳动权益的，工会可以依法要求用人单位承担责任；因履行集体合同发生争议，经协商解决不成的，工会可以依法申请仲裁、提起诉讼。 第二节　劳务派遣 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10257, '《中华人民共和国劳动合同法》', '第五十七条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第五十七条　经营劳务派遣业务应当具备下列条件: 　　（一）注册资本不得少于人民币二百万元； 　　（二）有与开展业务相适应的固定的经营场所和设施； 　　（三）有符合法律、行政法规规定的劳务派遣管理制度； 　　（四）法律、行政法规规定的其他条件。 　　经营劳务派遣业务，应当向劳动行政部门依法申请行政许可；经许可的，依法办理相应的公司登记。未经许可，任何单位和个人不得经营劳务派遣业务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10258, '《中华人民共和国劳动合同法》', '第五十八条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第五十八条　劳务派遣单位是本法所称用人单位，应当履行用人单位对劳动者的义务。劳务派遣单位与被派遣劳动者订立的劳动合同，除应当载明本法第十七条规定的事项外，还应当载明被派遣劳动者的用工单位以及派遣期限、工作岗位等情况。 　　劳务派遣单位应当与被派遣劳动者订立二年以上的固定期限劳动合同，按月支付劳动报酬；被派遣劳动者在无工作期间，劳务派遣单位应当按照所在地人民政府规定的最低工资标准，向其按月支付报酬。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10259, '《中华人民共和国劳动合同法》', '第五十九条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第五十九条　劳务派遣单位派遣劳动者应当与接受以劳务派遣形式用工的单位（以下称用工单位）订立劳务派遣协议。劳务派遣协议应当约定派遣岗位和人员数量、派遣期限、劳动报酬和社会保险费的数额与支付方式以及违反协议的责任。 　　用工单位应当根据工作岗位的实际需要与劳务派遣单位确定派遣期限，不得将连续用工期限分割订立数个短期劳务派遣协议。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10260, '《中华人民共和国劳动合同法》', '第六十条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十条　劳务派遣单位应当将劳务派遣协议的内容告知被派遣劳动者。 　　劳务派遣单位不得克扣用工单位按照劳务派遣协议支付给被派遣劳动者的劳动报酬。 　　劳务派遣单位和用工单位不得向被派遣劳动者收取费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10261, '《中华人民共和国劳动合同法》', '第六十一条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十一条　劳务派遣单位跨地区派遣劳动者的，被派遣劳动者享有的劳动报酬和劳动条件，按照用工单位所在地的标准执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10262, '《中华人民共和国劳动合同法》', '第六十二条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十二条　用工单位应当履行下列义务: 　　（一）执行国家劳动标准，提供相应的劳动条件和劳动保护； 　　（二）告知被派遣劳动者的工作要求和劳动报酬； 　　（三）支付加班费、绩效奖金，提供与工作岗位相关的福利待遇； 　　（四）对在岗被派遣劳动者进行工作岗位所必需的培训； 　　（五）连续用工的，实行正常的工资调整机制。 　　用工单位不得将被派遣劳动者再派遣到其他用人单位。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10263, '《中华人民共和国劳动合同法》', '第六十三条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十三条　被派遣劳动者享有与用工单位的劳动者同工同酬的权利。用工单位应当按照同工同酬原则，对被派遣劳动者与本单位同类岗位的劳动者实行相同的劳动报酬分配办法。用工单位无同类岗位劳动者的，参照用工单位所在地相同或者相近岗位劳动者的劳动报酬确定。 　　劳务派遣单位与被派遣劳动者订立的劳动合同和与用工单位订立的劳务派遣协议，载明或者约定的向被派遣劳动者支付的劳动报酬应当符合前款规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10264, '《中华人民共和国劳动合同法》', '第六十四条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十四条　被派遣劳动者有权在劳务派遣单位或者用工单位依法参加或者组织工会，维护自身的合法权益。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10265, '《中华人民共和国劳动合同法》', '第六十五条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十五条　被派遣劳动者可以依照本法第三十六条、第三十八条的规定与劳务派遣单位解除劳动合同。 　　被派遣劳动者有本法第三十九条和第四十条第一项、第二项规定情形的，用工单位可以将劳动者退回劳务派遣单位，劳务派遣单位依照本法有关规定，可以与劳动者解除劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10266, '《中华人民共和国劳动合同法》', '第六十六条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十六条　劳动合同用工是我国的企业基本用工形式。劳务派遣用工是补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。 　　前款规定的临时性工作岗位是指存续时间不超过六个月的岗位；辅助性工作岗位是指为主营业务岗位提供服务的非主营业务岗位；替代性工作岗位是指用工单位的劳动者因脱产学习、休假等原因无法工作的一定期间内，可以由其他劳动者替代工作的岗位。 　　用工单位应当严格控制劳务派遣用工数量，不得超过其用工总量的一定比例，具体比例由国务院劳动行政部门规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10267, '《中华人民共和国劳动合同法》', '第六十七条', '劳动', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十七条　用人单位不得设立劳务派遣单位向本单位或者所属单位派遣劳动者。 第三节　非全日制用工 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10268, '《中华人民共和国劳动合同法》', '第六十八条', '劳动', NULL, NULL, '第五章 　特别规定', '第三节 　非全日制用工　　', '第六十八条　非全日制用工，是指以小时计酬为主，劳动者在同一用人单位一般平均每日工作时间不超过四小时，每周工作时间累计不超过二十四小时的用工形式。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10269, '《中华人民共和国劳动合同法》', '第六十九条', '劳动', NULL, NULL, '第五章 　特别规定', '第三节 　非全日制用工　　', '第六十九条　非全日制用工双方当事人可以订立口头协议。 　　从事非全日制用工的劳动者可以与一个或者一个以上用人单位订立劳动合同；但是，后订立的劳动合同不得影响先订立的劳动合同的履行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10270, '《中华人民共和国劳动合同法》', '第七十条', '劳动', NULL, NULL, '第五章 　特别规定', '第三节 　非全日制用工　　', '第七十条　非全日制用工双方当事人不得约定试用期。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10271, '《中华人民共和国劳动合同法》', '第七十一条', '劳动', NULL, NULL, '第五章 　特别规定', '第三节 　非全日制用工　　', '第七十一条　非全日制用工双方当事人任何一方都可以随时通知对方终止用工。终止用工，用人单位不向劳动者支付经济补偿。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10272, '《中华人民共和国劳动合同法》', '第七十二条', '劳动', NULL, NULL, '第五章 　特别规定', '第三节 　非全日制用工　　', '第七十二条　非全日制用工小时计酬标准不得低于用人单位所在地人民政府规定的最低小时工资标准。 　　非全日制用工劳动报酬结算支付周期最长不得超过十五日。 第六章　监督检查 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10273, '《中华人民共和国劳动合同法》', '第七十三条', '劳动', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十三条　国务院劳动行政部门负责全国劳动合同制度实施的监督管理。 　　县级以上地方人民政府劳动行政部门负责本行政区域内劳动合同制度实施的监督管理。 　　县级以上各级人民政府劳动行政部门在劳动合同制度实施的监督管理工作中，应当听取工会、企业方面代表以及有关行业主管部门的意见。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10274, '《中华人民共和国劳动合同法》', '第七十四条', '劳动', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十四条　县级以上地方人民政府劳动行政部门依法对下列实施劳动合同制度的情况进行监督检查: 　　（一）用人单位制定直接涉及劳动者切身利益的规章制度及其执行的情况； 　　（二）用人单位与劳动者订立和解除劳动合同的情况； 　　（三）劳务派遣单位和用工单位遵守劳务派遣有关规定的情况； 　　（四）用人单位遵守国家关于劳动者工作时间和休息休假规定的情况； 　　（五）用人单位支付劳动合同约定的劳动报酬和执行最低工资标准的情况； 　　（六）用人单位参加各项社会保险和缴纳社会保险费的情况； 　　（七）法律、法规规定的其他劳动监察事项。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10275, '《中华人民共和国劳动合同法》', '第七十五条', '劳动', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十五条　县级以上地方人民政府劳动行政部门实施监督检查时，有权查阅与劳动合同、集体合同有关的材料，有权对劳动场所进行实地检查，用人单位和劳动者都应当如实提供有关情况和材料。 　　劳动行政部门的工作人员进行监督检查，应当出示证件，依法行使职权，文明执法。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10276, '《中华人民共和国劳动合同法》', '第七十六条', '劳动', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十六条　县级以上人民政府建设、卫生、安全生产监督管理等有关主管部门在各自职责范围内，对用人单位执行劳动合同制度的情况进行监督管理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10277, '《中华人民共和国劳动合同法》', '第七十七条', '劳动', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十七条　劳动者合法权益受到侵害的，有权要求有关部门依法处理，或者依法申请仲裁、提起诉讼。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10278, '《中华人民共和国劳动合同法》', '第七十八条', '劳动', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十八条　工会依法维护劳动者的合法权益，对用人单位履行劳动合同、集体合同的情况进行监督。用人单位违反劳动法律、法规和劳动合同、集体合同的，工会有权提出意见或者要求纠正；劳动者申请仲裁、提起诉讼的，工会依法给予支持和帮助。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10279, '《中华人民共和国劳动合同法》', '第七十九条', '劳动', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十九条　任何组织或者个人对违反本法的行为都有权举报，县级以上人民政府劳动行政部门应当及时核实、处理，并对举报有功人员给予奖励。 第七章　法律责任 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10280, '《中华人民共和国劳动合同法》', '第八十条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十条　用人单位直接涉及劳动者切身利益的规章制度违反法律、法规规定的，由劳动行政部门责令改正，给予警告；给劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10281, '《中华人民共和国劳动合同法》', '第八十一条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十一条　用人单位提供的劳动合同文本未载明本法规定的劳动合同必备条款或者用人单位未将劳动合同文本交付劳动者的，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10282, '《中华人民共和国劳动合同法》', '第八十二条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十二条　用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。 　　用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10283, '《中华人民共和国劳动合同法》', '第八十三条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十三条　用人单位违反本法规定与劳动者约定试用期的，由劳动行政部门责令改正；违法约定的试用期已经履行的，由用人单位以劳动者试用期满月工资为标准，按已经履行的超过法定试用期的期间向劳动者支付赔偿金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10284, '《中华人民共和国劳动合同法》', '第八十四条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十四条　用人单位违反本法规定，扣押劳动者居民身份证等证件的，由劳动行政部门责令限期退还劳动者本人，并依照有关法律规定给予处罚。 　　用人单位违反本法规定，以担保或者其他名义向劳动者收取财物的，由劳动行政部门责令限期退还劳动者本人，并以每人五百元以上二千元以下的标准处以罚款；给劳动者造成损害的，应当承担赔偿责任。 　　劳动者依法解除或者终止劳动合同，用人单位扣押劳动者档案或者其他物品的，依照前款规定处罚。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10285, '《中华人民共和国劳动合同法》', '第八十五条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十五条　用人单位有下列情形之一的，由劳动行政部门责令限期支付劳动报酬、加班费或者经济补偿；劳动报酬低于当地最低工资标准的，应当支付其差额部分；逾期不支付的，责令用人单位按应付金额百分之五十以上百分之一百以下的标准向劳动者加付赔偿金: 　　（一）未按照劳动合同的约定或者国家规定及时足额支付劳动者劳动报酬的； 　　（二）低于当地最低工资标准支付劳动者工资的； 　　（三）安排加班不支付加班费的； 　　（四）解除或者终止劳动合同，未依照本法规定向劳动者支付经济补偿的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10286, '《中华人民共和国劳动合同法》', '第八十六条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十六条　劳动合同依照本法第二十六条规定被确认无效，给对方造成损害的，有过错的一方应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10287, '《中华人民共和国劳动合同法》', '第八十七条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十七条　用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10288, '《中华人民共和国劳动合同法》', '第八十八条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十八条　用人单位有下列情形之一的，依法给予行政处罚；构成犯罪的，依法追究刑事责任；给劳动者造成损害的，应当承担赔偿责任: 　　（一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的； 　　（二）违章指挥或者强令冒险作业危及劳动者人身安全的； 　　（三）侮辱、体罚、殴打、非法搜查或者拘禁劳动者的； 　　（四）劳动条件恶劣、环境污染严重，给劳动者身心健康造成严重损害的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10289, '《中华人民共和国劳动合同法》', '第八十九条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十九条　用人单位违反本法规定未向劳动者出具解除或者终止劳动合同的书面证明，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10290, '《中华人民共和国劳动合同法》', '第九十条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十条　劳动者违反本法规定解除劳动合同，或者违反劳动合同中约定的保密义务或者竞业限制，给用人单位造成损失的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10291, '《中华人民共和国劳动合同法》', '第九十一条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十一条　用人单位招用与其他用人单位尚未解除或者终止劳动合同的劳动者，给其他用人单位造成损失的，应当承担连带赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10292, '《中华人民共和国劳动合同法》', '第九十二条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十二条　违反本法规定，未经许可，擅自经营劳务派遣业务的，由劳动行政部门责令停止违法行为，没收违法所得，并处违法所得一倍以上五倍以下的罚款；没有违法所得的，可以处五万元以下的罚款。 　　劳务派遣单位、用工单位违反本法有关劳务派遣规定的，由劳动行政部门责令限期改正；逾期不改正的，以每人五千元以上一万元以下的标准处以罚款，对劳务派遣单位，吊销其劳务派遣业务经营许可证。用工单位给被派遣劳动者造成损害的，劳务派遣单位与用工单位承担连带赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10293, '《中华人民共和国劳动合同法》', '第九十三条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十三条　对不具备合法经营资格的用人单位的违法犯罪行为，依法追究法律责任；劳动者已经付出劳动的，该单位或者其出资人应当依照本法有关规定向劳动者支付劳动报酬、经济补偿、赔偿金；给劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10294, '《中华人民共和国劳动合同法》', '第九十四条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十四条　个人承包经营违反本法规定招用劳动者，给劳动者造成损害的，发包的组织与个人承包经营者承担连带赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10295, '《中华人民共和国劳动合同法》', '第九十五条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十五条　劳动行政部门和其他有关主管部门及其工作人员玩忽职守、不履行法定职责，或者违法行使职权，给劳动者或者用人单位造成损害的，应当承担赔偿责任；对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。 第八章　附则 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10296, '《中华人民共和国劳动合同法》', '第九十六条', '劳动', NULL, NULL, '第八章 　附则　　', NULL, '第九十六条　事业单位与实行聘用制的工作人员订立、履行、变更、解除或者终止劳动合同，法律、行政法规或者国务院另有规定的，依照其规定；未作规定的，依照本法有关规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10297, '《中华人民共和国劳动合同法》', '第九十七条', '劳动', NULL, NULL, '第八章 　附则　　', NULL, '第九十七条　本法施行前已依法订立且在本法施行之日存续的劳动合同，继续履行；本法第十四条第二款第三项规定连续订立固定期限劳动合同的次数，自本法施行后续订固定期限劳动合同时开始计算。 　　本法施行前已建立劳动关系，尚未订立书面劳动合同的，应当自本法施行之日起一个月内订立。 　　本法施行之日存续的劳动合同在本法施行后解除或者终止，依照本法第四十六条规定应当支付经济补偿的，经济补偿年限自本法施行之日起计算；本法施行前按照当时有关规定，用人单位应当向劳动者支付经济补偿的，按照当时有关规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10298, '《中华人民共和国劳动合同法》', '第九十八条', '劳动', NULL, NULL, '第八章 　附则　　', NULL, '第九十八条　本法自2008年1月1日起施行。 分享 打印本页 关闭窗口', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10301, '《中华人民共和国劳动合同法实施条例》', '第一条', '劳动', NULL, NULL, '第一章 　总　则　　', NULL, '第一条　为了贯彻实施《中华人民共和国劳动合同法》（以下简称劳动合同法），制定本条例。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10302, '《中华人民共和国劳动合同法实施条例》', '第二条', '劳动', NULL, NULL, '第一章 　总　则　　', NULL, '第二条　各级人民政府和县级以上人民政府劳动行政等有关部门以及工会等组织，应当采取措施，推动劳动合同法的贯彻实施，促进劳动关系的和谐。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10303, '《中华人民共和国劳动合同法实施条例》', '第三条', '劳动', NULL, NULL, '第一章 　总　则　　', NULL, '第三条　依法成立的会计师事务所、律师事务所等合伙组织和基金会，属于劳动合同法规定的用人单位。 　　第二章　劳动合同的订立 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10304, '《中华人民共和国劳动合同法实施条例》', '第四条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第四条　劳动合同法规定的用人单位设立的分支机构，依法取得营业执照或者登记证书的，可以作为用人单位与劳动者订立劳动合同；未依法取得营业执照或者登记证书的，受用人单位委托可以与劳动者订立劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10305, '《中华人民共和国劳动合同法实施条例》', '第五条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第五条　自用工之日起一个月内，经用人单位书面通知后，劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，无需向劳动者支付经济补偿，但是应当依法向劳动者支付其实际工作时间的劳动报酬。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10306, '《中华人民共和国劳动合同法实施条例》', '第六条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第六条　用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并与劳动者补订书面劳动合同；劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，并依照劳动合同法第四十七条的规定支付经济补偿。 　　前款规定的用人单位向劳动者每月支付两倍工资的起算时间为用工之日起满一个月的次日，截止时间为补订书面劳动合同的前一日。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10307, '《中华人民共和国劳动合同法实施条例》', '第七条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第七条　用人单位自用工之日起满一年未与劳动者订立书面劳动合同的，自用工之日起满一个月的次日至满一年的前一日应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并视为自用工之日起满一年的当日已经与劳动者订立无固定期限劳动合同，应当立即与劳动者补订书面劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10308, '《中华人民共和国劳动合同法实施条例》', '第八条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第八条　劳动合同法第七条规定的职工名册，应当包括劳动者姓名、性别、公民身份号码、户籍地址及现住址、联系方式、用工形式、用工起始时间、劳动合同期限等内容。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10309, '《中华人民共和国劳动合同法实施条例》', '第九条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第九条　劳动合同法第十四条第二款规定的连续工作满１０年的起始时间，应当自用人单位用工之日起计算，包括劳动合同法施行前的工作年限。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10310, '《中华人民共和国劳动合同法实施条例》', '第十条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十条　劳动者非因本人原因从原用人单位被安排到新用人单位工作的，劳动者在原用人单位的工作年限合并计算为新用人单位的工作年限。原用人单位已经向劳动者支付经济补偿的，新用人单位在依法解除、终止劳动合同计算支付经济补偿的工作年限时，不再计算劳动者在原用人单位的工作年限。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10311, '《中华人民共和国劳动合同法实施条例》', '第十一条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十一条　除劳动者与用人单位协商一致的情形外，劳动者依照劳动合同法第十四条第二款的规定，提出订立无固定期限劳动合同的，用人单位应当与其订立无固定期限劳动合同。对劳动合同的内容，双方应当按照合法、公平、平等自愿、协商一致、诚实信用的原则协商确定；对协商不一致的内容，依照劳动合同法第十八条的规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10312, '《中华人民共和国劳动合同法实施条例》', '第十二条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十二条　地方各级人民政府及县级以上地方人民政府有关部门为安置就业困难人员提供的给予岗位补贴和社会保险补贴的公益性岗位，其劳动合同不适用劳动合同法有关无固定期限劳动合同的规定以及支付经济补偿的规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10313, '《中华人民共和国劳动合同法实施条例》', '第十三条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十三条　用人单位与劳动者不得在劳动合同法第四十四条规定的劳动合同终止情形之外约定其他的劳动合同终止条件。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10314, '《中华人民共和国劳动合同法实施条例》', '第十四条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十四条　劳动合同履行地与用人单位注册地不一致的，有关劳动者的最低工资标准、劳动保护、劳动条件、职业危害防护和本地区上年度职工月平均工资标准等事项，按照劳动合同履行地的有关规定执行；用人单位注册地的有关标准高于劳动合同履行地的有关标准，且用人单位与劳动者约定按照用人单位注册地的有关规定执行的，从其约定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10315, '《中华人民共和国劳动合同法实施条例》', '第十五条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十五条　劳动者在试用期的工资不得低于本单位相同岗位最低档工资的８０％或者不得低于劳动合同约定工资的８０％，并不得低于用人单位所在地的最低工资标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10316, '《中华人民共和国劳动合同法实施条例》', '第十六条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十六条　劳动合同法第二十二条第二款规定的培训费用，包括用人单位为了对劳动者进行专业技术培训而支付的有凭证的培训费用、培训期间的差旅费用以及因培训产生的用于该劳动者的其他直接费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10317, '《中华人民共和国劳动合同法实施条例》', '第十七条', '劳动', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十七条　劳动合同期满，但是用人单位与劳动者依照劳动合同法第二十二条的规定约定的服务期尚未到期的，劳动合同应当续延至服务期满；双方另有约定的，从其约定。 　　第三章　劳动合同的解除和终止 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10318, '《中华人民共和国劳动合同法实施条例》', '第十八条', '劳动', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第十八条　有下列情形之一的，依照劳动合同法规定的条件、程序，劳动者可以与用人单位解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同： 　　（一）劳动者与用人单位协商一致的； 　　（二）劳动者提前３０日以书面形式通知用人单位的； 　　（三）劳动者在试用期内提前３日通知用人单位的； 　　（四）用人单位未按照劳动合同约定提供劳动保护或者劳动条件的； 　　（五）用人单位未及时足额支付劳动报酬的； 　　（六）用人单位未依法为劳动者缴纳社会保险费的； 　　（七）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的； 　　（八）用人单位以欺诈、胁迫的手段或者乘人之危，使劳动者在违背真实意思的情况下订立或者变更劳动合同的； 　　（九）用人单位在劳动合同中免除自己的法定责任、排除劳动者权利的； 　　（十）用人单位违反法律、行政法规强制性规定的； 　　（十一）用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的； 　　（十二）用人单位违章指挥、强令冒险作业危及劳动者人身安全的； 　　（十三）法律、行政法规规定劳动者可以解除劳动合同的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10319, '《中华人民共和国劳动合同法实施条例》', '第十九条', '劳动', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第十九条　有下列情形之一的，依照劳动合同法规定的条件、程序，用人单位可以与劳动者解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同： 　　（一）用人单位与劳动者协商一致的； 　　（二）劳动者在试用期间被证明不符合录用条件的； 　　（三）劳动者严重违反用人单位的规章制度的； 　　（四）劳动者严重失职，营私舞弊，给用人单位造成重大损害的； 　　（五）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； 　　（六）劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的； 　　（七）劳动者被依法追究刑事责任的； 　　（八）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的； 　　（九）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； 　　（十）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的； 　　（十一）用人单位依照企业破产法规定进行重整的； 　　（十二）用人单位生产经营发生严重困难的； 　　（十三）企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的； 　　（十四）其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10320, '《中华人民共和国劳动合同法实施条例》', '第二十条', '劳动', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十条　用人单位依照劳动合同法第四十条的规定，选择额外支付劳动者一个月工资解除劳动合同的，其额外支付的工资应当按照该劳动者上一个月的工资标准确定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10321, '《中华人民共和国劳动合同法实施条例》', '第二十一条', '劳动', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十一条　劳动者达到法定退休年龄的，劳动合同终止。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10322, '《中华人民共和国劳动合同法实施条例》', '第二十二条', '劳动', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十二条　以完成一定工作任务为期限的劳动合同因任务完成而终止的，用人单位应当依照劳动合同法第四十七条的规定向劳动者支付经济补偿。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10323, '《中华人民共和国劳动合同法实施条例》', '第二十三条', '劳动', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十三条　用人单位依法终止工伤职工的劳动合同的，除依照劳动合同法第四十七条的规定支付经济补偿外，还应当依照国家有关工伤保险的规定支付一次性工伤医疗补助金和伤残就业补助金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10324, '《中华人民共和国劳动合同法实施条例》', '第二十四条', '劳动', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十四条　用人单位出具的解除、终止劳动合同的证明，应当写明劳动合同期限、解除或者终止劳动合同的日期、工作岗位、在本单位的工作年限。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10325, '《中华人民共和国劳动合同法实施条例》', '第二十五条', '劳动', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十五条　用人单位违反劳动合同法的规定解除或者终止劳动合同，依照劳动合同法第八十七条的规定支付了赔偿金的，不再支付经济补偿。赔偿金的计算年限自用工之日起计算。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10326, '《中华人民共和国劳动合同法实施条例》', '第二十六条', '劳动', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十六条　用人单位与劳动者约定了服务期，劳动者依照劳动合同法第三十八条的规定解除劳动合同的，不属于违反服务期的约定，用人单位不得要求劳动者支付违约金。 　　有下列情形之一，用人单位与劳动者解除约定服务期的劳动合同的，劳动者应当按照劳动合同的约定向用人单位支付违约金： 　　（一）劳动者严重违反用人单位的规章制度的； 　　（二）劳动者严重失职，营私舞弊，给用人单位造成重大损害的； 　　（三）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； 　　（四）劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的； 　　（五）劳动者被依法追究刑事责任的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10327, '《中华人民共和国劳动合同法实施条例》', '第二十七条', '劳动', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十七条　劳动合同法第四十七条规定的经济补偿的月工资按照劳动者应得工资计算，包括计时工资或者计件工资以及奖金、津贴和补贴等货币性收入。劳动者在劳动合同解除或者终止前１２个月的平均工资低于当地最低工资标准的，按照当地最低工资标准计算。劳动者工作不满１２个月的，按照实际工作的月数计算平均工资。 　　第四章　劳务派遣特别规定 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10328, '《中华人民共和国劳动合同法实施条例》', '第二十八条', '劳动', NULL, NULL, '第四章 　劳务派遣特别规定　　', NULL, '第二十八条　用人单位或者其所属单位出资或者合伙设立的劳务派遣单位，向本单位或者所属单位派遣劳动者的，属于劳动合同法第六十七条规定的不得设立的劳务派遣单位。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10329, '《中华人民共和国劳动合同法实施条例》', '第二十九条', '劳动', NULL, NULL, '第四章 　劳务派遣特别规定　　', NULL, '第二十九条　用工单位应当履行劳动合同法第六十二条规定的义务，维护被派遣劳动者的合法权益。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10330, '《中华人民共和国劳动合同法实施条例》', '第三十条', '劳动', NULL, NULL, '第四章 　劳务派遣特别规定　　', NULL, '第三十条　劳务派遣单位不得以非全日制用工形式招用被派遣劳动者。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10331, '《中华人民共和国劳动合同法实施条例》', '第三十一条', '劳动', NULL, NULL, '第四章 　劳务派遣特别规定　　', NULL, '第三十一条　劳务派遣单位或者被派遣劳动者依法解除、终止劳动合同的经济补偿，依照劳动合同法第四十六条、第四十七条的规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10332, '《中华人民共和国劳动合同法实施条例》', '第三十二条', '劳动', NULL, NULL, '第四章 　劳务派遣特别规定　　', NULL, '第三十二条　劳务派遣单位违法解除或者终止被派遣劳动者的劳动合同的，依照劳动合同法第四十八条的规定执行。 　　第五章　法津责任 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10333, '《中华人民共和国劳动合同法实施条例》', '第三十三条', '劳动', NULL, NULL, '第五章 　法津责任　　', NULL, '第三十三条　用人单位违反劳动合同法有关建立职工名册规定的，由劳动行政部门责令限期改正；逾期不改正的，由劳动行政部门处２０００元以上２万元以下的罚款。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10334, '《中华人民共和国劳动合同法实施条例》', '第三十四条', '劳动', NULL, NULL, '第五章 　法津责任　　', NULL, '第三十四条　用人单位依照劳动合同法的规定应当向劳动者每月支付两倍的工资或者应当向劳动者支付赔偿金而未支付的，劳动行政部门应当责令用人单位支付。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10335, '《中华人民共和国劳动合同法实施条例》', '第三十五条', '劳动', NULL, NULL, '第五章 　法津责任　　', NULL, '第三十五条　用工单位违反劳动合同法和本条例有关劳务派遣规定的，由劳动行政部门和其他有关主管部门责令改正；情节严重的，以每位被派遣劳动者１０００元以上５０００元以下的标准处以罚款；给被派遣劳动者造成损害的，劳务派遣单位和用工单位承担连带赔偿责任。 　　第六章　附　则 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10336, '《中华人民共和国劳动合同法实施条例》', '第三十六条', '劳动', NULL, NULL, '第六章 　附　则　　', NULL, '第三十六条　对违反劳动合同法和本条例的行为的投诉、举报，县级以上地方人民政府劳动行政部门依照《劳动保障监察条例》的规定处理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10337, '《中华人民共和国劳动合同法实施条例》', '第三十七条', '劳动', NULL, NULL, '第六章 　附　则　　', NULL, '第三十七条　劳动者与用人单位因订立、履行、变更、解除或者终止劳动合同发生争议的，依照《中华人民共和国劳动争议调解仲裁法》的规定处理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10338, '《中华人民共和国劳动合同法实施条例》', '第三十八条', '劳动', NULL, NULL, '第六章 　附　则　　', NULL, '第三十八条　本条例自公布之日起施行。 www.nt12333.com 南通劳动保障服务网提供资讯参考 重点招聘 　 　 　 　 　 关于我们 | 法律声明 | 资费标准 | 友情链接 | 设为首页| 加入收藏 | 联系我们 服务电话：88866428 13912400180 联系Email：halwd@126.com 联系QQ：583542580 联系地址：海安县鸿鹄劳动保障事务所 邮政编码：226600 南通劳动保障服务网 海安县鸿鹄劳动保障事务所 版权所有', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10401, '《中华人民共和国劳动争议调解仲裁法》', '第一条', '劳动', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第一条为了公正及时解决劳动争议，保护当事人合法权益，促进劳动关系和谐稳定，制定本法。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10402, '《中华人民共和国劳动争议调解仲裁法》', '第二条', '劳动', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第二条中华人民共和国境内的用人单位与劳动者发生的下列劳动争议，适用本法： 　　　 （一）因确认劳动关系发生的争议； 　　　 （二）因订立、履行、变更、解除和终止劳动合同发生的争议； 　　　 （三）因除名、辞退和辞职、离职发生的争议； 　　　 （四）因工作时间、休息休假、社会保险、福利、培训以及劳动保护发生的争议； 　　　 （五）因劳动报酬、工伤医疗费、经济补偿或者赔偿金等发生的争议； 　　　 （六）法律、法规规定的其他劳动争议。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10403, '《中华人民共和国劳动争议调解仲裁法》', '第三条', '劳动', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第三条解决劳动争议，应当根据事实，遵循合法、公正、及时、着重调解的原则，依法保护当事人的合法权益。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10404, '《中华人民共和国劳动争议调解仲裁法》', '第四条', '劳动', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第四条发生劳动争议，劳动者可以与用人单位协商，也可以请工会或者第三方共同与用人单位协商，达成和解协议。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10405, '《中华人民共和国劳动争议调解仲裁法》', '第五条', '劳动', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第五条发生劳动争议，当事人不愿协商、协商不成或者达成和解协议后不履行的，可以向调解组织申请调解；不愿调解、调解不成或者达成调解协议后不履行的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，除本法另有规定的外，可以向人民法院提起诉讼。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10406, '《中华人民共和国劳动争议调解仲裁法》', '第六条', '劳动', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第六条发生劳动争议，当事人对自己提出的主张，有责任提供证据。与争议事项有关的证据属于用人单位掌握管理的，用人单位应当提供；用人单位不提供的，应当承担不利后果。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10407, '《中华人民共和国劳动争议调解仲裁法》', '第七条', '劳动', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第七条发生劳动争议的劳动者一方在十人以上，并有共同请求的，可以推举代表参加调解、仲裁或者诉讼活动。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10408, '《中华人民共和国劳动争议调解仲裁法》', '第八条', '劳动', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第八条县级以上人民政府劳动行政部门会同工会和企业方面代表建立协调劳动关系三方机制，共同研究解决劳动争议的重大问题。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10409, '《中华人民共和国劳动争议调解仲裁法》', '第九条', '劳动', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第九条用人单位违反国家规定，拖欠或者未足额支付劳动报酬，或者拖欠工伤医疗费、经济补偿或者赔偿金的，劳动者可以向劳动行政部门投诉，劳动行政部门应当依法处理。 　　 　　第二章　调　　解 　　 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10410, '《中华人民共和国劳动争议调解仲裁法》', '第十条', '劳动', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十条发生劳动争议，当事人可以到下列调解组织申请调解： 　　　 （一）企业劳动争议调解委员会； 　　　 （二）依法设立的基层人民调解组织； 　　　 （三）在乡镇、街道设立的具有劳动争议调解职能的组织。 　　　 企业劳动争议调解委员会由职工代表和企业代表组成。职工代表由工会成员担任或者由全体职工推举产生，企业代表由企业负责人指定。企业劳动争议调解委员会主任由工会成员或者双方推举的人员担任。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10411, '《中华人民共和国劳动争议调解仲裁法》', '第十一条', '劳动', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十一条劳动争议调解组织的调解员应当由公道正派、联系群众、热心调解工作，并具有一定法律知识、政策水平和文化水平的成年公民担任。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10412, '《中华人民共和国劳动争议调解仲裁法》', '第十二条', '劳动', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十二条当事人申请劳动争议调解可以书面申请，也可以口头申请。口头申请的，调解组织应当当场记录申请人基本情况、申请调解的争议事项、理由和时间。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10413, '《中华人民共和国劳动争议调解仲裁法》', '第十三条', '劳动', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十三条调解劳动争议，应当充分听取双方当事人对事实和理由的陈述，耐心疏导，帮助其达成协议。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10414, '《中华人民共和国劳动争议调解仲裁法》', '第十四条', '劳动', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十四条经调解达成协议的，应当制作调解协议书。 　　　 调解协议书由双方当事人签名或者盖章，经调解员签名并加盖调解组织印章后生效，对双方当事人具有约束力，当事人应当履行。 　　　 自劳动争议调解组织收到调解申请之日起十五日内未达成调解协议的，当事人可以依法申请仲裁。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10415, '《中华人民共和国劳动争议调解仲裁法》', '第十五条', '劳动', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十五条达成调解协议后，一方当事人在协议约定期限内不履行调解协议的，另一方当事人可以依法申请仲裁。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10416, '《中华人民共和国劳动争议调解仲裁法》', '第十六条', '劳动', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十六条因支付拖欠劳动报酬、工伤医疗费、经济补偿或者赔偿金事项达成调解协议，用人单位在协议约定期限内不履行的，劳动者可以持调解协议书依法向人民法院申请支付令。人民法院应当依法发出支付令。 　　 　　第三章　仲　　裁 　　 　　　 第一节一般规定 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10417, '《中华人民共和国劳动争议调解仲裁法》', '第十七条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第十七条劳动争议仲裁委员会按照统筹规划、合理布局和适应实际需要的原则设立。省、自治区人民政府可以决定在市、县设立；直辖市人民政府可以决定在区、县设立。直辖市、设区的市也可以设立一个或者若干个劳动争议仲裁委员会。劳动争议仲裁委员会不按行政区划层层设立。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10418, '《中华人民共和国劳动争议调解仲裁法》', '第十八条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第十八条国务院劳动行政部门依照本法有关规定制定仲裁规则。省、自治区、直辖市人民政府劳动行政部门对本行政区域的劳动争议仲裁工作进行指导。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10419, '《中华人民共和国劳动争议调解仲裁法》', '第十九条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第十九条劳动争议仲裁委员会由劳动行政部门代表、工会代表和企业方面代表组成。劳动争议仲裁委员会组成人员应当是单数。 　　　 劳动争议仲裁委员会依法履行下列职责： 　　　 （一）聘任、解聘专职或者兼职仲裁员； 　　　 （二）受理劳动争议案件； 　　　 （三）讨论重大或者疑难的劳动争议案件； 　　　 （四）对仲裁活动进行监督。 　　　 劳动争议仲裁委员会下设办事机构，负责办理劳动争议仲裁委员会的日常工作。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10420, '《中华人民共和国劳动争议调解仲裁法》', '第二十条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十条劳动争议仲裁委员会应当设仲裁员名册。 　　　 仲裁员应当公道正派并符合下列条件之一： 　　　 （一）曾任审判员的； 　　　 （二）从事法律研究、教学工作并具有中级以上职称的； 　　　 （三）具有法律知识、从事人力资源管理或者工会等专业工作满五年的； 　　　 （四）律师执业满三年的。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10421, '《中华人民共和国劳动争议调解仲裁法》', '第二十一条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十一条劳动争议仲裁委员会负责管辖本区域内发生的劳动争议。 　　　 劳动争议由劳动合同履行地或者用人单位所在地的劳动争议仲裁委员会管辖。双方当事人分别向劳动合同履行地和用人单位所在地的劳动争议仲裁委员会申请仲裁的，由劳动合同履行地的劳动争议仲裁委员会管辖。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10422, '《中华人民共和国劳动争议调解仲裁法》', '第二十二条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十二条发生劳动争议的劳动者和用人单位为劳动争议仲裁案件的双方当事人。 　　　 劳务派遣单位或者用工单位与劳动者发生劳动争议的，劳务派遣单位和用工单位为共同当事人。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10423, '《中华人民共和国劳动争议调解仲裁法》', '第二十三条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十三条与劳动争议案件的处理结果有利害关系的第三人，可以申请参加仲裁活动或者由劳动争议仲裁委员会通知其参加仲裁活动。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10424, '《中华人民共和国劳动争议调解仲裁法》', '第二十四条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十四条当事人可以委托代理人参加仲裁活动。委托他人参加仲裁活动，应当向劳动争议仲裁委员会提交有委托人签名或者盖章的委托书，委托书应当载明委托事项和权限。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10425, '《中华人民共和国劳动争议调解仲裁法》', '第二十五条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十五条丧失或者部分丧失民事行为能力的劳动者，由其法定代理人代为参加仲裁活动；无法定代理人的，由劳动争议仲裁委员会为其指定代理人。劳动者死亡的，由其近亲属或者代理人参加仲裁活动。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10426, '《中华人民共和国劳动争议调解仲裁法》', '第二十六条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十六条劳动争议仲裁公开进行，但当事人协议不公开进行或者涉及国家秘密、商业秘密和个人隐私的除外。 　　　 第二节申请和受理 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10427, '《中华人民共和国劳动争议调解仲裁法》', '第二十七条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第二节 申请和受理　　　', '第二十七条劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。 　　　 前款规定的仲裁时效，因当事人一方向对方当事人主张权利，或者向有关部门请求权利救济，或者对方当事人同意履行义务而中断。从中断时起，仲裁时效期间重新计算。 　　　 因不可抗力或者有其他正当理由，当事人不能在本条第一款规定的仲裁时效期间申请仲裁的，仲裁时效中止。从中止时效的原因消除之日起，仲裁时效期间继续计算。 　　　 劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10428, '《中华人民共和国劳动争议调解仲裁法》', '第二十八条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第二节 申请和受理　　　', '第二十八条申请人申请仲裁应当提交书面仲裁申请，并按照被申请人人数提交副本。 　　　 仲裁申请书应当载明下列事项： 　　　 （一）劳动者的姓名、性别、年龄、职业、工作单位和住所，用人单位的名称、住所和法定代表人或者主要负责人的姓名、职务； 　　　 （二）仲裁请求和所根据的事实、理由； 　　　 （三）证据和证据来源、证人姓名和住所。 　　　 书写仲裁申请确有困难的，可以口头申请，由劳动争议仲裁委员会记入笔录，并告知对方当事人。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10429, '《中华人民共和国劳动争议调解仲裁法》', '第二十九条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第二节 申请和受理　　　', '第二十九条劳动争议仲裁委员会收到仲裁申请之日起五日内，认为符合受理条件的，应当受理，并通知申请人；认为不符合受理条件的，应当书面通知申请人不予受理，并说明理由。对劳动争议仲裁委员会不予受理或者逾期未作出决定的，申请人可以就该劳动争议事项向人民法院提起诉讼。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10430, '《中华人民共和国劳动争议调解仲裁法》', '第三十条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第二节 申请和受理　　　', '第三十条劳动争议仲裁委员会受理仲裁申请后，应当在五日内将仲裁申请书副本送达被申请人。 　　　 被申请人收到仲裁申请书副本后，应当在十日内向劳动争议仲裁委员会提交答辩书。劳动争议仲裁委员会收到答辩书后，应当在五日内将答辩书副本送达申请人。被申请人未提交答辩书的，不影响仲裁程序的进行。 　　　 第三节开庭和裁决 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10431, '《中华人民共和国劳动争议调解仲裁法》', '第三十一条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十一条劳动争议仲裁委员会裁决劳动争议案件实行仲裁庭制。仲裁庭由三名仲裁员组成，设首席仲裁员。简单劳动争议案件可以由一名仲裁员独任仲裁。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10432, '《中华人民共和国劳动争议调解仲裁法》', '第三十二条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十二条劳动争议仲裁委员会应当在受理仲裁申请之日起五日内将仲裁庭的组成情况书面通知当事人。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10433, '《中华人民共和国劳动争议调解仲裁法》', '第三十三条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十三条仲裁员有下列情形之一，应当回避，当事人也有权以口头或者书面方式提出回避申请： 　　　 （一）是本案当事人或者当事人、代理人的近亲属的； 　　　 （二）与本案有利害关系的； 　　　 （三）与本案当事人、代理人有其他关系，可能影响公正裁决的； 　　　 （四）私自会见当事人、代理人，或者接受当事人、代理人的请客送礼的。 　　　 劳动争议仲裁委员会对回避申请应当及时作出决定，并以口头或者书面方式通知当事人。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10434, '《中华人民共和国劳动争议调解仲裁法》', '第三十四条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十四条仲裁员有本法第三十三条第四项规定情形，或者有索贿受贿、徇私舞弊、枉法裁决行为的，应当依法承担法律责任。劳动争议仲裁委员会应当将其解聘。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10435, '《中华人民共和国劳动争议调解仲裁法》', '第三十五条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十五条仲裁庭应当在开庭五日前，将开庭日期、地点书面通知双方当事人。当事人有正当理由的，可以在开庭三日前请求延期开庭。是否延期，由劳动争议仲裁委员会决定。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10436, '《中华人民共和国劳动争议调解仲裁法》', '第三十六条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十六条申请人收到书面通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，可以视为撤回仲裁申请。 　　　 被申请人收到书面通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，可以缺席裁决。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10437, '《中华人民共和国劳动争议调解仲裁法》', '第三十七条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十七条仲裁庭对专门性问题认为需要鉴定的，可以交由当事人约定的鉴定机构鉴定；当事人没有约定或者无法达成约定的，由仲裁庭指定的鉴定机构鉴定。 　　　 根据当事人的请求或者仲裁庭的要求，鉴定机构应当派鉴定人参加开庭。当事人经仲裁庭许可，可以向鉴定人提问。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10438, '《中华人民共和国劳动争议调解仲裁法》', '第三十八条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十八条当事人在仲裁过程中有权进行质证和辩论。质证和辩论终结时，首席仲裁员或者独任仲裁员应当征询当事人的最后意见。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10439, '《中华人民共和国劳动争议调解仲裁法》', '第三十九条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十九条当事人提供的证据经查证属实的，仲裁庭应当将其作为认定事实的根据。 　　　 劳动者无法提供由用人单位掌握管理的与仲裁请求有关的证据，仲裁庭可以要求用人单位在指定期限内提供。用人单位在指定期限内不提供的，应当承担不利后果。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10440, '《中华人民共和国劳动争议调解仲裁法》', '第四十条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十条仲裁庭应当将开庭情况记入笔录。当事人和其他仲裁参加人认为对自己陈述的记录有遗漏或者差错的，有权申请补正。如果不予补正，应当记录该申请。 　　　 笔录由仲裁员、记录人员、当事人和其他仲裁参加人签名或者盖章。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10441, '《中华人民共和国劳动争议调解仲裁法》', '第四十一条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十一条当事人申请劳动争议仲裁后，可以自行和解。达成和解协议的，可以撤回仲裁申请。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10442, '《中华人民共和国劳动争议调解仲裁法》', '第四十二条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十二条仲裁庭在作出裁决前，应当先行调解。 　　　 调解达成协议的，仲裁庭应当制作调解书。 　　　 调解书应当写明仲裁请求和当事人协议的结果。调解书由仲裁员签名，加盖劳动争议仲裁委员会印章，送达双方当事人。调解书经双方当事人签收后，发生法律效力。 　　　 调解不成或者调解书送达前，一方当事人反悔的，仲裁庭应当及时作出裁决。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10443, '《中华人民共和国劳动争议调解仲裁法》', '第四十三条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十三条仲裁庭裁决劳动争议案件，应当自劳动争议仲裁委员会受理仲裁申请之日起四十五日内结束。案情复杂需要延期的，经劳动争议仲裁委员会主任批准，可以延期并书面通知当事人，但是延长期限不得超过十五日。逾期未作出仲裁裁决的，当事人可以就该劳动争议事项向人民法院提起诉讼。 　　　 仲裁庭裁决劳动争议案件时，其中一部分事实已经清楚，可以就该部分先行裁决。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10444, '《中华人民共和国劳动争议调解仲裁法》', '第四十四条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十四条仲裁庭对追索劳动报酬、工伤医疗费、经济补偿或者赔偿金的案件，根据当事人的申请，可以裁决先予执行，移送人民法院执行。 　　　 仲裁庭裁决先予执行的，应当符合下列条件： 　　　 （一）当事人之间权利义务关系明确； 　　　 （二）不先予执行将严重影响申请人的生活。 　　　 劳动者申请先予执行的，可以不提供担保。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10445, '《中华人民共和国劳动争议调解仲裁法》', '第四十五条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十五条裁决应当按照多数仲裁员的意见作出，少数仲裁员的不同意见应当记入笔录。仲裁庭不能形成多数意见时，裁决应当按照首席仲裁员的意见作出。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10446, '《中华人民共和国劳动争议调解仲裁法》', '第四十六条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十六条裁决书应当载明仲裁请求、争议事实、裁决理由、裁决结果和裁决日期。裁决书由仲裁员签名，加盖劳动争议仲裁委员会印章。对裁决持不同意见的仲裁员，可以签名，也可以不签名。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10447, '《中华人民共和国劳动争议调解仲裁法》', '第四十七条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十七条下列劳动争议，除本法另有规定的外，仲裁裁决为终局裁决，裁决书自作出之日起发生法律效力： 　　　 （一）追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，不超过当地月最低工资标准十二个月金额的争议； 　　　 （二）因执行国家的劳动标准在工作时间、休息休假、社会保险等方面发生的争议。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10448, '《中华人民共和国劳动争议调解仲裁法》', '第四十八条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十八条劳动者对本法第四十七条规定的仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10449, '《中华人民共和国劳动争议调解仲裁法》', '第四十九条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十九条用人单位有证据证明本法第四十七条规定的仲裁裁决有下列情形之一，可以自收到仲裁裁决书之日起三十日内向劳动争议仲裁委员会所在地的中级人民法院申请撤销裁决： 　　　 （一）适用法律、法规确有错误的； 　　　 （二）劳动争议仲裁委员会无管辖权的； 　　　 （三）违反法定程序的； 　　　 （四）裁决所根据的证据是伪造的； 　　　 （五）对方当事人隐瞒了足以影响公正裁决的证据的； 　　　 （六）仲裁员在仲裁该案时有索贿受贿、徇私舞弊、枉法裁决行为的。 　　　 人民法院经组成合议庭审查核实裁决有前款规定情形之一的，应当裁定撤销。 　　　 仲裁裁决被人民法院裁定撤销的，当事人可以自收到裁定书之日起十五日内就该劳动争议事项向人民法院提起诉讼。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10450, '《中华人民共和国劳动争议调解仲裁法》', '第五十条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第五十条当事人对本法第四十七条规定以外的其他劳动争议案件的仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼；期满不起诉的，裁决书发生法律效力。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10451, '《中华人民共和国劳动争议调解仲裁法》', '第五十一条', '劳动', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第五十一条当事人对发生法律效力的调解书、裁决书，应当依照规定的期限履行。一方当事人逾期不履行的，另一方当事人可以依照民事诉讼法的有关规定向人民法院申请执行。受理申请的人民法院应当依法执行。 　　 　　第四章　附　　则 　　 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10452, '《中华人民共和国劳动争议调解仲裁法》', '第五十二条', '劳动', NULL, NULL, '第四章 　附　　则　　　　　', NULL, '第五十二条事业单位实行聘用制的工作人员与本单位发生劳动争议的，依照本法执行；法律、行政法规或者国务院另有规定的，依照其规定。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10453, '《中华人民共和国劳动争议调解仲裁法》', '第五十三条', '劳动', NULL, NULL, '第四章 　附　　则　　　　　', NULL, '第五十三条劳动争议仲裁不收费。劳动争议仲裁委员会的经费由财政予以保障。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10454, '《中华人民共和国劳动争议调解仲裁法》', '第五十四条', '劳动', NULL, NULL, '第四章 　附　　则　　　　　', NULL, '第五十四条本法自2008年5月1日起施行。 　　 皖ICP备 050001008 中国科学院合肥物质科学研究院 版权所有　 地址:安徽省合肥市蜀山湖路350号 邮编:230031 电话:0551-5591245 电子邮件:yzxx@hfcas.ac.cn', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10501, '《工伤保险条例》', '第一条', '劳动', NULL, NULL, '第一章 　总　　则　　', NULL, '第一条　为了保障因工作遭受事故伤害或者患职业病的职工获得医疗救治和经济补偿，促进工伤预防和职业康复，分散用人单位的工伤风险，制定本条例。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10502, '《工伤保险条例》', '第二条', '劳动', NULL, NULL, '第一章 　总　　则　　', NULL, '第二条　中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织和有雇工的个体工商户（以下称用人单位）应当依照本条例规定参加工伤保险，为本单位全部职工或者雇工（以下称职工）缴纳工伤保险费。 　　中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织的职工和个体工商户的雇工，均有依照本条例的规定享受工伤保险待遇的权利。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10503, '《工伤保险条例》', '第三条', '劳动', NULL, NULL, '第一章 　总　　则　　', NULL, '第三条　工伤保险费的征缴按照《社会保险费征缴暂行条例》关于基本养老保险费、基本医疗保险费、失业保险费的征缴规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10504, '《工伤保险条例》', '第四条', '劳动', NULL, NULL, '第一章 　总　　则　　', NULL, '第四条　用人单位应当将参加工伤保险的有关情况在本单位内公示。 　　用人单位和职工应当遵守有关安全生产和职业病防治的法律法规，执行安全卫生规程和标准，预防工伤事故发生，避免和减少职业病危害。 　　职工发生工伤时，用人单位应当采取措施使工伤职工得到及时救治。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10505, '《工伤保险条例》', '第五条', '劳动', NULL, NULL, '第一章 　总　　则　　', NULL, '第五条　国务院社会保险行政部门负责全国的工伤保险工作。 　　县级以上地方各级人民政府社会保险行政部门负责本行政区域内的工伤保险工作。 　　社会保险行政部门按照国务院有关规定设立的社会保险经办机构（以下称经办机构）具体承办工伤保险事务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10506, '《工伤保险条例》', '第六条', '劳动', NULL, NULL, '第一章 　总　　则　　', NULL, '第六条　社会保险行政部门等部门制定工伤保险的政策、标准，应当征求工会组织、用人单位代表的意见。 第二章　工伤保险基金 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10507, '《工伤保险条例》', '第七条', '劳动', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第七条　工伤保险基金由用人单位缴纳的工伤保险费、工伤保险基金的利息和依法纳入工伤保险基金的其他资金构成。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10508, '《工伤保险条例》', '第八条', '劳动', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第八条　工伤保险费根据以支定收、收支平衡的原则，确定费率。 　　国家根据不同行业的工伤风险程度确定行业的差别费率，并根据工伤保险费使用、工伤发生率等情况在每个行业内确定若干费率档次。行业差别费率及行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。 　　统筹地区经办机构根据用人单位工伤保险费使用、工伤发生率等情况，适用所属行业内相应的费率档次确定单位缴费费率。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10509, '《工伤保险条例》', '第九条', '劳动', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第九条　国务院社会保险行政部门应当定期了解全国各统筹地区工伤保险基金收支情况，及时提出调整行业差别费率及行业内费率档次的方案，报国务院批准后公布施行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10510, '《工伤保险条例》', '第十条', '劳动', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第十条　用人单位应当按时缴纳工伤保险费。职工个人不缴纳工伤保险费。 　　用人单位缴纳工伤保险费的数额为本单位职工工资总额乘以单位缴费费率之积。 　　对难以按照工资总额缴纳工伤保险费的行业，其缴纳工伤保险费的具体方式，由国务院社会保险行政部门规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10511, '《工伤保险条例》', '第十一条', '劳动', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第十一条　工伤保险基金逐步实行省级统筹。 　　跨地区、生产流动性较大的行业，可以采取相对集中的方式异地参加统筹地区的工伤保险。具体办法由国务院社会保险行政部门会同有关行业的主管部门制定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10512, '《工伤保险条例》', '第十二条', '劳动', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第十二条　工伤保险基金存入社会保障基金财政专户，用于本条例规定的工伤保险待遇，劳动能力鉴定，工伤预防的宣传、培训等费用，以及法律、法规规定的用于工伤保险的其他费用的支付。 　　工伤预防费用的提取比例、使用和管理的具体办法，由国务院社会保险行政部门会同国务院财政、卫生行政、安全生产监督管理等部门规定。 　　任何单位或者个人不得将工伤保险基金用于投资运营、兴建或者改建办公场所、发放奖金，或者挪作其他用途。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10513, '《工伤保险条例》', '第十三条', '劳动', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第十三条　工伤保险基金应当留有一定比例的储备金，用于统筹地区重大事故的工伤保险待遇支付；储备金不足支付的，由统筹地区的人民政府垫付。储备金占基金总额的具体比例和储备金的使用办法，由省、自治区、直辖市人民政府规定。 第三章　工伤认定 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10514, '《工伤保险条例》', '第十四条', '劳动', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十四条　职工有下列情形之一的，应当认定为工伤： 　　（一）在工作时间和工作场所内，因工作原因受到事故伤害的； 　　（二）工作时间前后在工作场所内，从事与工作有关的预备性或者收尾性工作受到事故伤害的； 　　（三）在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的； 　　（四）患职业病的； 　　（五）因工外出期间，由于工作原因受到伤害或者发生事故下落不明的； 　　（六）在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的； 　　（七）法律、行政法规规定应当认定为工伤的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10515, '《工伤保险条例》', '第十五条', '劳动', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十五条　职工有下列情形之一的，视同工伤： 　　（一）在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的； 　　（二）在抢险救灾等维护国家利益、公共利益活动中受到伤害的； 　　（三）职工原在军队服役，因战、因公负伤致残，已取得革命伤残军人证，到用人单位后旧伤复发的。 　　职工有前款第（一）项、第（二）项情形的，按照本条例的有关规定享受工伤保险待遇；职工有前款第（三）项情形的，按照本条例的有关规定享受除一次性伤残补助金以外的工伤保险待遇。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10516, '《工伤保险条例》', '第十六条', '劳动', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十六条　职工符合本条例第十四条、第十五条的规定，但是有下列情形之一的，不得认定为工伤或者视同工伤： 　　（一）故意犯罪的； 　　（二）醉酒或者吸毒的； 　　（三）自残或者自杀的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10517, '《工伤保险条例》', '第十七条', '劳动', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十七条　职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。 　　用人单位未按前款规定提出工伤认定申请的，工伤职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接向用人单位所在地统筹地区社会保险行政部门提出工伤认定申请。 　　按照本条第一款规定应当由省级社会保险行政部门进行工伤认定的事项，根据属地原则由用人单位所在地的设区的市级社会保险行政部门办理。 　　用人单位未在本条第一款规定的时限内提交工伤认定申请，在此期间发生符合本条例规定的工伤待遇等有关费用由该用人单位负担。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10518, '《工伤保险条例》', '第十八条', '劳动', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十八条　提出工伤认定申请应当提交下列材料： 　　（一）工伤认定申请表； 　　（二）与用人单位存在劳动关系（包括事实劳动关系）的证明材料； 　　（三）医疗诊断证明或者职业病诊断证明书（或者职业病诊断鉴定书）。 　　工伤认定申请表应当包括事故发生的时间、地点、原因以及职工伤害程度等基本情况。 　　工伤认定申请人提供材料不完整的，社会保险行政部门应当一次性书面告知工伤认定申请人需要补正的全部材料。申请人按照书面告知要求补正材料后，社会保险行政部门应当受理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10519, '《工伤保险条例》', '第十九条', '劳动', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十九条　社会保险行政部门受理工伤认定申请后，根据审核需要可以对事故伤害进行调查核实，用人单位、职工、工会组织、医疗机构以及有关部门应当予以协助。职业病诊断和诊断争议的鉴定，依照职业病防治法的有关规定执行。对依法取得职业病诊断证明书或者职业病诊断鉴定书的，社会保险行政部门不再进行调查核实。 　　职工或者其近亲属认为是工伤，用人单位不认为是工伤的，由用人单位承担举证责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10520, '《工伤保险条例》', '第二十条', '劳动', NULL, NULL, '第三章 　工伤认定　　', NULL, '第二十条　社会保险行政部门应当自受理工伤认定申请之日起60日内作出工伤认定的决定，并书面通知申请工伤认定的职工或者其近亲属和该职工所在单位。 　　社会保险行政部门对受理的事实清楚、权利义务明确的工伤认定申请，应当在15日内作出工伤认定的决定。 　　作出工伤认定决定需要以司法机关或者有关行政主管部门的结论为依据的，在司法机关或者有关行政主管部门尚未作出结论期间，作出工伤认定决定的时限中止。 　　社会保险行政部门工作人员与工伤认定申请人有利害关系的，应当回避。 第四章　劳动能力鉴定 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10521, '《工伤保险条例》', '第二十一条', '劳动', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十一条　职工发生工伤，经治疗伤情相对稳定后存在残疾、影响劳动能力的，应当进行劳动能力鉴定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10522, '《工伤保险条例》', '第二十二条', '劳动', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十二条　劳动能力鉴定是指劳动功能障碍程度和生活自理障碍程度的等级鉴定。 　　劳动功能障碍分为十个伤残等级，最重的为一级，最轻的为十级。 　　生活自理障碍分为三个等级：生活完全不能自理、生活大部分不能自理和生活部分不能自理。 　　劳动能力鉴定标准由国务院社会保险行政部门会同国务院卫生行政部门等部门制定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10523, '《工伤保险条例》', '第二十三条', '劳动', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十三条　劳动能力鉴定由用人单位、工伤职工或者其近亲属向设区的市级劳动能力鉴定委员会提出申请，并提供工伤认定决定和职工工伤医疗的有关资料。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10524, '《工伤保险条例》', '第二十四条', '劳动', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十四条　省、自治区、直辖市劳动能力鉴定委员会和设区的市级劳动能力鉴定委员会分别由省、自治区、直辖市和设区的市级社会保险行政部门、卫生行政部门、工会组织、经办机构代表以及用人单位代表组成。 　　劳动能力鉴定委员会建立医疗卫生专家库。列入专家库的医疗卫生专业技术人员应当具备下列条件： 　　（一）具有医疗卫生高级专业技术职务任职资格； 　　（二）掌握劳动能力鉴定的相关知识； 　　（三）具有良好的职业品德。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10525, '《工伤保险条例》', '第二十五条', '劳动', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十五条　设区的市级劳动能力鉴定委员会收到劳动能力鉴定申请后，应当从其建立的医疗卫生专家库中随机抽取3名或者5名相关专家组成专家组，由专家组提出鉴定意见。设区的市级劳动能力鉴定委员会根据专家组的鉴定意见作出工伤职工劳动能力鉴定结论；必要时，可以委托具备资格的医疗机构协助进行有关的诊断。 　　设区的市级劳动能力鉴定委员会应当自收到劳动能力鉴定申请之日起60日内作出劳动能力鉴定结论，必要时，作出劳动能力鉴定结论的期限可以延长30日。劳动能力鉴定结论应当及时送达申请鉴定的单位和个人。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10526, '《工伤保险条例》', '第二十六条', '劳动', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十六条　申请鉴定的单位或者个人对设区的市级劳动能力鉴定委员会作出的鉴定结论不服的，可以在收到该鉴定结论之日起15日内向省、自治区、直辖市劳动能力鉴定委员会提出再次鉴定申请。省、自治区、直辖市劳动能力鉴定委员会作出的劳动能力鉴定结论为最终结论。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10527, '《工伤保险条例》', '第二十七条', '劳动', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十七条　劳动能力鉴定工作应当客观、公正。劳动能力鉴定委员会组成人员或者参加鉴定的专家与当事人有利害关系的，应当回避。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10528, '《工伤保险条例》', '第二十八条', '劳动', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十八条　自劳动能力鉴定结论作出之日起1年后，工伤职工或者其近亲属、所在单位或者经办机构认为伤残情况发生变化的，可以申请劳动能力复查鉴定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10529, '《工伤保险条例》', '第二十九条', '劳动', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十九条　劳动能力鉴定委员会依照本条例第二十六条和第二十八条的规定进行再次鉴定和复查鉴定的期限，依照本条例第二十五条第二款的规定执行。 第五章　工伤保险待遇 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10530, '《工伤保险条例》', '第三十条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十条　职工因工作遭受事故伤害或者患职业病进行治疗，享受工伤医疗待遇。 　　职工治疗工伤应当在签订服务协议的医疗机构就医，情况紧急时可以先到就近的医疗机构急救。 　　治疗工伤所需费用符合工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准的，从工伤保险基金支付。工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准，由国务院社会保险行政部门会同国务院卫生行政部门、食品药品监督管理部门等部门规定。 　　职工住院治疗工伤的伙食补助费，以及经医疗机构出具证明，报经办机构同意，工伤职工到统筹地区以外就医所需的交通、食宿费用从工伤保险基金支付，基金支付的具体标准由统筹地区人民政府规定。 　　工伤职工治疗非工伤引发的疾病，不享受工伤医疗待遇，按照基本医疗保险办法处理。 　　工伤职工到签订服务协议的医疗机构进行工伤康复的费用，符合规定的，从工伤保险基金支付。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10531, '《工伤保险条例》', '第三十一条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十一条　社会保险行政部门作出认定为工伤的决定后发生行政复议、行政诉讼的，行政复议和行政诉讼期间不停止支付工伤职工治疗工伤的医疗费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10532, '《工伤保险条例》', '第三十二条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十二条　工伤职工因日常生活或者就业需要，经劳动能力鉴定委员会确认，可以安装假肢、矫形器、假眼、假牙和配置轮椅等辅助器具，所需费用按照国家规定的标准从工伤保险基金支付。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10533, '《工伤保险条例》', '第三十三条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十三条　职工因工作遭受事故伤害或者患职业病需要暂停工作接受工伤医疗的，在停工留薪期内，原工资福利待遇不变，由所在单位按月支付。 　　停工留薪期一般不超过12个月。伤情严重或者情况特殊，经设区的市级劳动能力鉴定委员会确认，可以适当延长，但延长不得超过12个月。工伤职工评定伤残等级后，停发原待遇，按照本章的有关规定享受伤残待遇。工伤职工在停工留薪期满后仍需治疗的，继续享受工伤医疗待遇。 　　生活不能自理的工伤职工在停工留薪期需要护理的，由所在单位负责。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10534, '《工伤保险条例》', '第三十四条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十四条　工伤职工已经评定伤残等级并经劳动能力鉴定委员会确认需要生活护理的，从工伤保险基金按月支付生活护理费。 　　生活护理费按照生活完全不能自理、生活大部分不能自理或者生活部分不能自理3个不同等级支付，其标准分别为统筹地区上年度职工月平均工资的50%、40%或者30%。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10535, '《工伤保险条例》', '第三十五条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十五条　职工因工致残被鉴定为一级至四级伤残的，保留劳动关系，退出工作岗位，享受以下待遇： 　　（一）从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：一级伤残为27个月的本人工资，二级伤残为25个月的本人工资，三级伤残为23个月的本人工资，四级伤残为21个月的本人工资； 　　（二）从工伤保险基金按月支付伤残津贴，标准为：一级伤残为本人工资的90%，二级伤残为本人工资的85%，三级伤残为本人工资的80%，四级伤残为本人工资的75%。伤残津贴实际金额低于当地最低工资标准的，由工伤保险基金补足差额； 　　（三）工伤职工达到退休年龄并办理退休手续后，停发伤残津贴，按照国家有关规定享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，由工伤保险基金补足差额。 　　职工因工致残被鉴定为一级至四级伤残的，由用人单位和职工个人以伤残津贴为基数，缴纳基本医疗保险费。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10536, '《工伤保险条例》', '第三十六条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十六条　职工因工致残被鉴定为五级、六级伤残的，享受以下待遇： 　　（一）从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：五级伤残为18个月的本人工资，六级伤残为16个月的本人工资； 　　（二）保留与用人单位的劳动关系，由用人单位安排适当工作。难以安排工作的，由用人单位按月发给伤残津贴，标准为：五级伤残为本人工资的70%，六级伤残为本人工资的60%，并由用人单位按照规定为其缴纳应缴纳的各项社会保险费。伤残津贴实际金额低于当地最低工资标准的，由用人单位补足差额。 　　经工伤职工本人提出，该职工可以与用人单位解除或者终止劳动关系，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10537, '《工伤保险条例》', '第三十七条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十七条　职工因工致残被鉴定为七级至十级伤残的，享受以下待遇： 　　（一）从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：七级伤残为13个月的本人工资，八级伤残为11个月的本人工资，九级伤残为9个月的本人工资，十级伤残为7个月的本人工资； 　　（二）劳动、聘用合同期满终止，或者职工本人提出解除劳动、聘用合同的，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10538, '《工伤保险条例》', '第三十八条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十八条　工伤职工工伤复发，确认需要治疗的，享受本条例第三十条、第三十二条和第三十三条规定的工伤待遇。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10539, '《工伤保险条例》', '第三十九条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十九条　职工因工死亡，其近亲属按照下列规定从工伤保险基金领取丧葬补助金、供养亲属抚恤金和一次性工亡补助金： 　　（一）丧葬补助金为6个月的统筹地区上年度职工月平均工资； 　　（二）供养亲属抚恤金按照职工本人工资的一定比例发给由因工死亡职工生前提供主要生活来源、无劳动能力的亲属。标准为：配偶每月40%，其他亲属每人每月30%，孤寡老人或者孤儿每人每月在上述标准的基础上增加10%。核定的各供养亲属的抚恤金之和不应高于因工死亡职工生前的工资。供养亲属的具体范围由国务院社会保险行政部门规定； 　　（三）一次性工亡补助金标准为上一年度全国城镇居民人均可支配收入的20倍。 　　伤残职工在停工留薪期内因工伤导致死亡的，其近亲属享受本条第一款规定的待遇。 　　一级至四级伤残职工在停工留薪期满后死亡的，其近亲属可以享受本条第一款第（一）项、第（二）项规定的待遇。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10540, '《工伤保险条例》', '第四十条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十条　伤残津贴、供养亲属抚恤金、生活护理费由统筹地区社会保险行政部门根据职工平均工资和生活费用变化等情况适时调整。调整办法由省、自治区、直辖市人民政府规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10541, '《工伤保险条例》', '第四十一条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十一条　职工因工外出期间发生事故或者在抢险救灾中下落不明的，从事故发生当月起3个月内照发工资，从第4个月起停发工资，由工伤保险基金向其供养亲属按月支付供养亲属抚恤金。生活有困难的，可以预支一次性工亡补助金的50%。职工被人民法院宣告死亡的，按照本条例第三十九条职工因工死亡的规定处理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10542, '《工伤保险条例》', '第四十二条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十二条　工伤职工有下列情形之一的，停止享受工伤保险待遇： 　　（一）丧失享受待遇条件的； 　　（二）拒不接受劳动能力鉴定的； 　　（三）拒绝治疗的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10543, '《工伤保险条例》', '第四十三条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十三条　用人单位分立、合并、转让的，承继单位应当承担原用人单位的工伤保险责任；原用人单位已经参加工伤保险的，承继单位应当到当地经办机构办理工伤保险变更登记。 　　用人单位实行承包经营的，工伤保险责任由职工劳动关系所在单位承担。 　　职工被借调期间受到工伤事故伤害的，由原用人单位承担工伤保险责任，但原用人单位与借调单位可以约定补偿办法。 　　企业破产的，在破产清算时依法拨付应当由单位支付的工伤保险待遇费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10544, '《工伤保险条例》', '第四十四条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十四条　职工被派遣出境工作，依据前往国家或者地区的法律应当参加当地工伤保险的，参加当地工伤保险，其国内工伤保险关系中止；不能参加当地工伤保险的，其国内工伤保险关系不中止。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10545, '《工伤保险条例》', '第四十五条', '劳动', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十五条　职工再次发生工伤，根据规定应当享受伤残津贴的，按照新认定的伤残等级享受伤残津贴待遇。 第六章　监督管理 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10546, '《工伤保险条例》', '第四十六条', '劳动', NULL, NULL, '第六章 　监督管理　　', NULL, '第四十六条　经办机构具体承办工伤保险事务，履行下列职责： 　　（一）根据省、自治区、直辖市人民政府规定，征收工伤保险费； 　　（二）核查用人单位的工资总额和职工人数，办理工伤保险登记，并负责保存用人单位缴费和职工享受工伤保险待遇情况的记录； 　　（三）进行工伤保险的调查、统计； 　　（四）按照规定管理工伤保险基金的支出； 　　（五）按照规定核定工伤保险待遇； 　　（六）为工伤职工或者其近亲属免费提供咨询服务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10547, '《工伤保险条例》', '第四十七条', '劳动', NULL, NULL, '第六章 　监督管理　　', NULL, '第四十七条　经办机构与医疗机构、辅助器具配置机构在平等协商的基础上签订服务协议，并公布签订服务协议的医疗机构、辅助器具配置机构的名单。具体办法由国务院社会保险行政部门分别会同国务院卫生行政部门、民政部门等部门制定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10548, '《工伤保险条例》', '第四十八条', '劳动', NULL, NULL, '第六章 　监督管理　　', NULL, '第四十八条　经办机构按照协议和国家有关目录、标准对工伤职工医疗费用、康复费用、辅助器具费用的使用情况进行核查，并按时足额结算费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10549, '《工伤保险条例》', '第四十九条', '劳动', NULL, NULL, '第六章 　监督管理　　', NULL, '第四十九条　经办机构应当定期公布工伤保险基金的收支情况，及时向社会保险行政部门提出调整费率的建议。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10550, '《工伤保险条例》', '第五十条', '劳动', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十条　社会保险行政部门、经办机构应当定期听取工伤职工、医疗机构、辅助器具配置机构以及社会各界对改进工伤保险工作的意见。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10551, '《工伤保险条例》', '第五十一条', '劳动', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十一条　社会保险行政部门依法对工伤保险费的征缴和工伤保险基金的支付情况进行监督检查。 　　财政部门和审计机关依法对工伤保险基金的收支、管理情况进行监督。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10552, '《工伤保险条例》', '第五十二条', '劳动', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十二条　任何组织和个人对有关工伤保险的违法行为，有权举报。社会保险行政部门对举报应当及时调查，按照规定处理，并为举报人保密。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10553, '《工伤保险条例》', '第五十三条', '劳动', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十三条　工会组织依法维护工伤职工的合法权益，对用人单位的工伤保险工作实行监督。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10554, '《工伤保险条例》', '第五十四条', '劳动', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十四条　职工与用人单位发生工伤待遇方面的争议，按照处理劳动争议的有关规定处理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10555, '《工伤保险条例》', '第五十五条', '劳动', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十五条　有下列情形之一的，有关单位或者个人可以依法申请行政复议，也可以依法向人民法院提起行政诉讼： 　　（一）申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定申请不予受理的决定不服的； 　　（二）申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定结论不服的； 　　（三）用人单位对经办机构确定的单位缴费费率不服的； 　　（四）签订服务协议的医疗机构、辅助器具配置机构认为经办机构未履行有关协议或者规定的； 　　（五）工伤职工或者其近亲属对经办机构核定的工伤保险待遇有异议的。 第七章　法律责任 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10556, '《工伤保险条例》', '第五十六条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第五十六条　单位或者个人违反本条例第十二条规定挪用工伤保险基金，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分或者纪律处分。被挪用的基金由社会保险行政部门追回，并入工伤保险基金；没收的违法所得依法上缴国库。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10557, '《工伤保险条例》', '第五十七条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第五十七条　社会保险行政部门工作人员有下列情形之一的，依法给予处分；情节严重，构成犯罪的，依法追究刑事责任： 　　（一）无正当理由不受理工伤认定申请，或者弄虚作假将不符合工伤条件的人员认定为工伤职工的； 　　（二）未妥善保管申请工伤认定的证据材料，致使有关证据灭失的； 　　（三）收受当事人财物的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10558, '《工伤保险条例》', '第五十八条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第五十八条　经办机构有下列行为之一的，由社会保险行政部门责令改正，对直接负责的主管人员和其他责任人员依法给予纪律处分；情节严重，构成犯罪的，依法追究刑事责任；造成当事人经济损失的，由经办机构依法承担赔偿责任： 　　（一）未按规定保存用人单位缴费和职工享受工伤保险待遇情况记录的； 　　（二）不按规定核定工伤保险待遇的； 　　（三）收受当事人财物的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10559, '《工伤保险条例》', '第五十九条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第五十九条　医疗机构、辅助器具配置机构不按服务协议提供服务的，经办机构可以解除服务协议。 　　经办机构不按时足额结算费用的，由社会保险行政部门责令改正；医疗机构、辅助器具配置机构可以解除服务协议。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10560, '《工伤保险条例》', '第六十条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第六十条　用人单位、工伤职工或者其近亲属骗取工伤保险待遇，医疗机构、辅助器具配置机构骗取工伤保险基金支出的，由社会保险行政部门责令退还，处骗取金额2倍以上5倍以下的罚款；情节严重，构成犯罪的，依法追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10561, '《工伤保险条例》', '第六十一条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第六十一条　从事劳动能力鉴定的组织或者个人有下列情形之一的，由社会保险行政部门责令改正，处2000元以上1万元以下的罚款；情节严重，构成犯罪的，依法追究刑事责任： 　　（一）提供虚假鉴定意见的； 　　（二）提供虚假诊断证明的； 　　（三）收受当事人财物的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10562, '《工伤保险条例》', '第六十二条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第六十二条　用人单位依照本条例规定应当参加工伤保险而未参加的，由社会保险行政部门责令限期参加，补缴应当缴纳的工伤保险费，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，处欠缴数额1倍以上3倍以下的罚款。 　　依照本条例规定应当参加工伤保险而未参加工伤保险的用人单位职工发生工伤的，由该用人单位按照本条例规定的工伤保险待遇项目和标准支付费用。 　　用人单位参加工伤保险并补缴应当缴纳的工伤保险费、滞纳金后，由工伤保险基金和用人单位依照本条例的规定支付新发生的费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10563, '《工伤保险条例》', '第六十三条', '劳动', NULL, NULL, '第七章 　法律责任　　', NULL, '第六十三条　用人单位违反本条例第十九条的规定，拒不协助社会保险行政部门对事故进行调查核实的，由社会保险行政部门责令改正，处2000元以上2万元以下的罚款。 第八章　附　　则 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10564, '《工伤保险条例》', '第六十四条', '劳动', NULL, NULL, '第八章 　附　　则　　', NULL, '第六十四条　本条例所称工资总额，是指用人单位直接支付给本单位全部职工的劳动报酬总额。 　　本条例所称本人工资，是指工伤职工因工作遭受事故伤害或者患职业病前12个月平均月缴费工资。本人工资高于统筹地区职工平均工资300%的，按照统筹地区职工平均工资的300%计算；本人工资低于统筹地区职工平均工资60%的，按照统筹地区职工平均工资的60%计算。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10565, '《工伤保险条例》', '第六十五条', '劳动', NULL, NULL, '第八章 　附　　则　　', NULL, '第六十五条　公务员和参照公务员法管理的事业单位、社会团体的工作人员因工作遭受事故伤害或者患职业病的，由所在单位支付费用。具体办法由国务院社会保险行政部门会同国务院财政部门规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10566, '《工伤保险条例》', '第六十六条', '劳动', NULL, NULL, '第八章 　附　　则　　', NULL, '第六十六条　无营业执照或者未经依法登记、备案的单位以及被依法吊销营业执照或者撤销登记、备案的单位的职工受到事故伤害或者患职业病的，由该单位向伤残职工或者死亡职工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇；用人单位不得使用童工，用人单位使用童工造成童工伤残、死亡的，由该单位向童工或者童工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇。具体办法由国务院社会保险行政部门规定。 　　前款规定的伤残职工或者死亡职工的近亲属就赔偿数额与单位发生争议的，以及前款规定的童工或者童工的近亲属就赔偿数额与单位发生争议的，按照处理劳动争议的有关规定处理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10567, '《工伤保险条例》', '第六十七条', '劳动', NULL, NULL, '第八章 　附　　则　　', NULL, '第六十七条　本条例自2004年1月1日起施行。本条例施行前已受到事故伤害或者患职业病的职工尚未完成工伤认定的，按照本条例的规定执行。 【E-mail推荐 】', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10601, '《失业保险条例》', '第一条', '劳动', NULL, NULL, '第一章 　总则', NULL, '第一条　为了保障失业人员失业期间的基本生活，促进其再就业，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10602, '《失业保险条例》', '第二条', '劳动', NULL, NULL, '第一章 　总则', NULL, '第二条　城镇企业事业单位、城镇企业事业单位职工依照本条例的规定，缴纳失业保险费。 城镇企业事业单位失业人员依照本条例的规定，享受失业保险待遇。 本条所称城镇企业，是指国有企业、城镇集体企业、外商投资企业、城镇私营企业以及其他城镇企业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10603, '《失业保险条例》', '第三条', '劳动', NULL, NULL, '第一章 　总则', NULL, '第三条　国务院劳动保障行政部门主管全国的失业保险工作。县级以上地方各级人民政府劳动保障行政部门主管本行政区域内的失业保险工作。劳动保障行政部门按照国务院规定设立的经办失业保险业务的社会保险经办机构依照本条例的规定，具体承办失业保险工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10604, '《失业保险条例》', '第四条', '劳动', NULL, NULL, '第一章 　总则', NULL, '第四条　失业保险费按照国家有关规定征缴。 第二章　失业保险基金', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10605, '《失业保险条例》', '第五条', '劳动', NULL, NULL, '第二章 　失业保险基金', NULL, '第五条　失业保险基金由下列各项构成： (一)城镇企业事业单位、城镇企业事业单位职工缴纳的失业保险费； (二)失业保险基金的利息； (三)财政补贴； (四)依法纳入失业保险基金的其他资金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10606, '《失业保险条例》', '第六条', '劳动', NULL, NULL, '第二章 　失业保险基金', NULL, '第六条　城镇企业事业单位按照本单位工资总额的2%缴纳失业保险费。城镇企业事业单位职工按照本人工资的1%缴纳失业保险费。城镇企业事业单位招用的农民合同制工人本人不缴纳失业保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10607, '《失业保险条例》', '第七条', '劳动', NULL, NULL, '第二章 　失业保险基金', NULL, '第七条　失业保险基金在直辖市和设区的市实行全市统筹；其他地区的统筹层次由省、自治区人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10608, '《失业保险条例》', '第八条', '劳动', NULL, NULL, '第二章 　失业保险基金', NULL, '第八条　省、自治区可以建立失业保险调剂金。 失业保险调剂金以统筹地区依法应当征收的失业保险费为基数，按照省、自治区人民政府规定的比例筹集。 统筹地区的失业保险基金不敷使用时，由失业保险调剂金调剂、地方财政补贴。 失业保险调剂金的筹集、调剂使用以及地方财政补贴的具体办法，由省、自治区人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10609, '《失业保险条例》', '第九条', '劳动', NULL, NULL, '第二章 　失业保险基金', NULL, '第九条　省、自治区、直辖市人民政府根据本行政区域失业人员数量和失业保险基金数额，报经国务院批准，可以适当调整本行政区域失业保险费的费率。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10610, '《失业保险条例》', '第十条', '劳动', NULL, NULL, '第二章 　失业保险基金', NULL, '第十条　失业保险基金用于下列支出： (一)失业保险金； (二)领取失业保险金期间的医疗补助金； (三)领取失业保险金期间死亡的失业人员的丧葬补助金和其供养的配偶、直系亲属的抚恤金； (四)领取失业保险金期间接受职业培训、职业介绍的补贴，补贴的办法和标准由省、自治区、直辖市人民政府规定； (五)国务院规定或者批准的与失业保险有关的其他费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10611, '《失业保险条例》', '第十一条', '劳动', NULL, NULL, '第二章 　失业保险基金', NULL, '第十一条　失业保险基金必须存入财政部门在国有商业银行开设的社会保障基金财政专户，实行收支两条线管理，由财政部门依法进行监督。 存入银行和按照国家规定购买国债的失业保险基金，分别按照城乡居民同期存款利率和国债利息计息。失业保险基金的利息并入失业保险基金。 失业保险基金专款专用，不得挪作他用，不得用于平衡财政收支。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10612, '《失业保险条例》', '第十二条', '劳动', NULL, NULL, '第二章 　失业保险基金', NULL, '第十二条　失业保险基金收支的预算、决算，由统筹地区社会保险经办机构编制，经同级劳动保障行政部门复核、同级财政部门审核，报同级人民政府审批。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10613, '《失业保险条例》', '第十三条', '劳动', NULL, NULL, '第二章 　失业保险基金', NULL, '第十三条　失业保险基金的财务制度和会计制度按照国家有关规定执行。 第三章　失业保险待遇', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10614, '《失业保险条例》', '第十四条', '劳动', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十四条　具备下列条件的失业人员，可以领取失业保险金： (一)按照规定参加失业保险，所在单位和本人已按照规定履行缴费义务满1年的； (二)非因本人意愿中断就业的； (三)已办理失业登记，并有求职要求的。 失业人员在领取失业保险金期间，按照规定同时享受其他失业保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10615, '《失业保险条例》', '第十五条', '劳动', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十五条　失业人员在领取失业保险金期间有下列情形之一的，停止领取失业保险金，并同时停止享受其他失业保险待遇： (一)重新就业的； (二)应征服兵役的； (三)移居境外的； (四)享受基本养老保险待遇的； (五)被判刑收监执行或者被劳动教养的； (六)无正当理由，拒不接受当地人民政府指定的部门或者机构介绍的工作的； (七)有法律、行政法规规定的其他情形的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10616, '《失业保险条例》', '第十六条', '劳动', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十六条　城镇企业事业单位应当及时为失业人员出具终止或者解除劳动关系的证明，告知其按照规定享受失业保险待遇的权利，并将失业人员的名单自终止或者解除劳动关系之日起7日内报社会保险经办机构备案。 城镇企业事业单位职工失业后，应当持本单位为其出具的终止或者解除劳动关系的证明，及时到指定的社会保险经办机构办理失业登记。失业保险金自办理失业登记之日起计算。 失业保险金由社会保险经办机构按月发放。社会保险经办机构为失业人员开具领取失业保险金的单证，失业人员凭单证到指定银行领取失业保险金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10617, '《失业保险条例》', '第十七条', '劳动', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十七条　失业人员失业前所在单位和本人按照规定累计缴费时间满1年不足5年的，领取失业保险金的期限最长为12个月；累计缴费时间满5年不足10年的，领取失业保险金的期限最长为18个月；累计缴费时间10年以上的，领取失业保险金的期限最长为24个月。重新就业后，再次失业的，缴费时间重新计算，领取失业保险金的期限可以与前次失业应领取而尚未领取的失业保险金的期限合并计算，但是最长不得超过24个月。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10618, '《失业保险条例》', '第十八条', '劳动', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十八条　失业保险金的标准，按照低于当地最低工资标准、高于城市居民最低生活保障标准的水平，由省、自治区、直辖市人民政府确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10619, '《失业保险条例》', '第十九条', '劳动', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十九条　失业人员在领取失业保险金期间患病就医的，可以按照规定向社会保险经办机构申请领取医疗补助金。医疗补助金的标准由省、自治区、直辖市人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10620, '《失业保险条例》', '第二十条', '劳动', NULL, NULL, '第三章 　失业保险待遇', NULL, '第二十条　失业人员在领取失业保险金期间死亡的，参照当地对在职职工的规定，对其家属一次性发给丧葬补助金和抚恤金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10621, '《失业保险条例》', '第二十一条', '劳动', NULL, NULL, '第三章 　失业保险待遇', NULL, '第二十一条　单位招用的农民合同制工人连续工作满1年，本单位并已缴纳失业保险费，劳动合同期满未续订或者提前解除劳动合同的，由社会保险经办机构根据其工作时间长短，对其支付一次性生活补助。补助的办法和标准由省、自治区、直辖市人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10622, '《失业保险条例》', '第二十二条', '劳动', NULL, NULL, '第三章 　失业保险待遇', NULL, '第二十二条　城镇企业事业单位成建制跨统筹地区转移，失业人员跨统筹地区流动的，失业保险关系随之转迁。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10623, '《失业保险条例》', '第二十三条', '劳动', NULL, NULL, '第三章 　失业保险待遇', NULL, '第二十三条　失业人员符合城市居民最低生活保障条件的，按照规定享受城市居民最低生活保障待遇。 第四章　管理和监督', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10624, '《失业保险条例》', '第二十四条', '劳动', NULL, NULL, '第四章 　管理和监督', NULL, '第二十四条　劳动保障行政部门管理失业保险工作，履行下列职责： (一)贯彻实施失业保险法律、法规； (二)指导社会保险经办机构的工作； (三)对失业保险费的征收和失业保险待遇的支付进行监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10625, '《失业保险条例》', '第二十五条', '劳动', NULL, NULL, '第四章 　管理和监督', NULL, '第二十五条　社会保险经办机构具体承办失业保险工作，履行下列职责： (一)负责失业人员的登记、调查、统计； (二)按照规定负责失业保险基金的管理； (三)按照规定核定失业保险待遇，开具失业人员在指定银行领取失业保险金和其他补助金的单证； (四)拨付失业人员职业培训、职业介绍补贴费用； (五)为失业人员提供免费咨询服务； (六)国家规定由其履行的其他职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10626, '《失业保险条例》', '第二十六条', '劳动', NULL, NULL, '第四章 　管理和监督', NULL, '第二十六条　财政部门和审计部门依法对失业保险基金的收支、管理情况进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10627, '《失业保险条例》', '第二十七条', '劳动', NULL, NULL, '第四章 　管理和监督', NULL, '第二十七条　社会保险经办机构所需经费列入预算，由财政拨付。 第五章　罚则', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10628, '《失业保险条例》', '第二十八条', '劳动', NULL, NULL, '第五章 　罚则', NULL, '第二十八条　不符合享受失业保险待遇条件，骗取失业保险金和其他失业保险待遇的，由社会保险经办机构责令退还；情节严重的，由劳动保障行政部门处骗取金额1倍以上3倍以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10629, '《失业保险条例》', '第二十九条', '劳动', NULL, NULL, '第五章 　罚则', NULL, '第二十九条　社会保险经办机构工作人员违反规定向失业人员开具领取失业保险金或者享受其他失业保险待遇单证，致使失业保险基金损失的，由劳动保障行政部门责令追回；情节严重的，依法给予行政处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10630, '《失业保险条例》', '第三十条', '劳动', NULL, NULL, '第五章 　罚则', NULL, '第三十条　劳动保障行政部门和社会保险经办机构的工作人员滥用职权、徇私舞弊、玩忽职守，造成失业保险基金损失的，由劳动保障行政部门追回损失的失业保险基金；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10631, '《失业保险条例》', '第三十一条', '劳动', NULL, NULL, '第五章 　罚则', NULL, '第三十一条　任何单位、个人挪用失业保险基金的，追回挪用的失业保险基金；有违法所得的，没收违法所得，并入失业保险基金；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。 第六章　附则', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10632, '《失业保险条例》', '第三十二条', '劳动', NULL, NULL, '第六章 　附则', NULL, '第三十二条　省、自治区、直辖市人民政府根据当地实际情况，可以决定本条例适用于本行政区域内的社会团体及其专职人员、民办非企业单位及其职工、有雇工的城镇个体工商户及其雇工。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10633, '《失业保险条例》', '第三十三条', '劳动', NULL, NULL, '第六章 　附则', NULL, '第三十三条　本条例自发布之日起施行。1993年4月12日国务院发布的《国有企业职工待业保险规定》同时废止。 返回 顶部 中华人民共和国司法部 版权所有 京ICP备0505517 司法部信息中心 运维保障 Copyright © 2017 All Rights Reserved', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10701, '《职工带薪年休假条例》', '第一条', '劳动', NULL, NULL, NULL, NULL, '第一条 为了维护职工休息休假权利，调动职工工作积极性，根据劳动法和公务员法，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10702, '《职工带薪年休假条例》', '第二条', '劳动', NULL, NULL, NULL, NULL, '第二条 机关、团体、企业、事业单位、民办非企业单位、有雇工的个体工商户等单位的职工连续工作1年以上的，享受带薪年休假（以下简称年休假）。单位应当保证职工享受年休假。职工在年休假期间享受与正常工作期间相同的工资收入。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10703, '《职工带薪年休假条例》', '第三条', '劳动', NULL, NULL, NULL, NULL, '第三条 职工累计工作已满1年不满10年的，年休假5天；已满10年不满20年的，年休假10天；已满20年的，年休假15天。 国家法定休假日、休息日不计入年休假的假期。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10704, '《职工带薪年休假条例》', '第四条', '劳动', NULL, NULL, NULL, NULL, '第四条 职工有下列情形之一的，不享受当年的年休假： （一）职工依法享受寒暑假，其休假天数多于年休假天数的； （二）职工请事假累计20天以上且单位按照规定不扣工资的； （三）累计工作满1年不满10年的职工，请病假累计2个月以上的； （四）累计工作满10年不满20年的职工，请病假累计3个月以上的； （五）累计工作满20年以上的职工，请病假累计4个月以上的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10705, '《职工带薪年休假条例》', '第五条', '劳动', NULL, NULL, NULL, NULL, '第五条 单位根据生产、工作的具体情况，并考虑职工本人意愿，统筹安排职工年休假。 年休假在1个年度内可以集中安排，也可以分段安排，一般不跨年度安排。单位因生产、工作特点确有必要跨年度安排职工年休假的，可以跨1个年度安排。 单位确因工作需要不能安排职工休年休假的，经职工本人同意，可以不安排职工休年休假。对职工应休未休的年休假天数，单位应当按照该职工日工资收入的300%支付年休假工资报酬。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10706, '《职工带薪年休假条例》', '第六条', '劳动', NULL, NULL, NULL, NULL, '第六条 县级以上地方人民政府人事部门、劳动保障部门应当依据职权对单位执行本条例的情况主动进行监督检查。 工会组织依法维护职工的年休假权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10707, '《职工带薪年休假条例》', '第七条', '劳动', NULL, NULL, NULL, NULL, '第七条 单位不安排职工休年休假又不依照本条例规定给予年休假工资报酬的，由县级以上地方人民政府人事部门或者劳动保障部门依据职权责令限期改正；对逾期不改正的，除责令该单位支付年休假工资报酬外，单位还应当按照年休假工资报酬的数额向职工加付赔偿金；对拒不支付年休假工资报酬、赔偿金的，属于公务员和参照公务员法管理的人员所在单位的，对直接负责的主管人员以及其他直接责任人员依法给予处分；属于其他单位的，由劳动保障部门、人事部门或者职工申请人民法院强制执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10708, '《职工带薪年休假条例》', '第八条', '劳动', NULL, NULL, NULL, NULL, '第八条 职工与单位因年休假发生的争议，依照国家有关法律、行政法规的规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10709, '《职工带薪年休假条例》', '第九条', '劳动', NULL, NULL, NULL, NULL, '第九条 国务院人事部门、国务院劳动保障部门依据职权，分别制定本条例的实施办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10710, '《职工带薪年休假条例》', '第十条', '劳动', NULL, NULL, NULL, NULL, '第十条 本条例自2008年1月1日起施行。 【E-mail推荐 】', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10801, '《女职工劳动保护特别规定》', '第一条', '劳动', NULL, NULL, NULL, NULL, '第一条　为了减少和解决女职工在劳动中因生理特点造成的特殊困难，保护女职工健康，制定本规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10802, '《女职工劳动保护特别规定》', '第二条', '劳动', NULL, NULL, NULL, NULL, '第二条　中华人民共和国境内的国家机关、企业、事业单位、社会团体、个体经济组织以及其他社会组织等用人单位及其女职工，适用本规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10803, '《女职工劳动保护特别规定》', '第三条', '劳动', NULL, NULL, NULL, NULL, '第三条　用人单位应当加强女职工劳动保护，采取措施改善女职工劳动安全卫生条件，对女职工进行劳动安全卫生知识培训。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10804, '《女职工劳动保护特别规定》', '第四条', '劳动', NULL, NULL, NULL, NULL, '第四条　用人单位应当遵守女职工禁忌从事的劳动范围的规定。用人单位应当将本单位属于女职工禁忌从事的劳动范围的岗位书面告知女职工。 　　女职工禁忌从事的劳动范围由本规定附录列示。国务院安全生产监督管理部门会同国务院人力资源社会保障行政部门、国务院卫生行政部门根据经济社会发展情况，对女职工禁忌从事的劳动范围进行调整。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10805, '《女职工劳动保护特别规定》', '第五条', '劳动', NULL, NULL, NULL, NULL, '第五条　用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10806, '《女职工劳动保护特别规定》', '第六条', '劳动', NULL, NULL, NULL, NULL, '第六条　女职工在孕期不能适应原劳动的，用人单位应当根据医疗机构的证明，予以减轻劳动量或者安排其他能够适应的劳动。 　　对怀孕7个月以上的女职工，用人单位不得延长劳动时间或者安排夜班劳动，并应当在劳动时间内安排一定的休息时间。 　　怀孕女职工在劳动时间内进行产前检查，所需时间计入劳动时间。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10807, '《女职工劳动保护特别规定》', '第七条', '劳动', NULL, NULL, NULL, NULL, '第七条　女职工生育享受98天产假，其中产前可以休假15天；难产的，增加产假15天；生育多胞胎的，每多生育1个婴儿，增加产假15天。 　　女职工怀孕未满4个月流产的，享受15天产假；怀孕满4个月流产的，享受42天产假。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10808, '《女职工劳动保护特别规定》', '第八条', '劳动', NULL, NULL, NULL, NULL, '第八条　女职工产假期间的生育津贴，对已经参加生育保险的，按照用人单位上年度职工月平均工资的标准由生育保险基金支付；对未参加生育保险的，按照女职工产假前工资的标准由用人单位支付。 　　女职工生育或者流产的医疗费用，按照生育保险规定的项目和标准，对已经参加生育保险的，由生育保险基金支付；对未参加生育保险的，由用人单位支付。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10809, '《女职工劳动保护特别规定》', '第九条', '劳动', NULL, NULL, NULL, NULL, '第九条　对哺乳未满1周岁婴儿的女职工，用人单位不得延长劳动时间或者安排夜班劳动。 　　用人单位应当在每天的劳动时间内为哺乳期女职工安排1小时哺乳时间；女职工生育多胞胎的，每多哺乳1个婴儿每天增加1小时哺乳时间。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10810, '《女职工劳动保护特别规定》', '第十条', '劳动', NULL, NULL, NULL, NULL, '第十条　女职工比较多的用人单位应当根据女职工的需要，建立女职工卫生室、孕妇休息室、哺乳室等设施，妥善解决女职工在生理卫生、哺乳方面的困难。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10811, '《女职工劳动保护特别规定》', '第十一条', '劳动', NULL, NULL, NULL, NULL, '第十一条　在劳动场所，用人单位应当预防和制止对女职工的性骚扰。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10812, '《女职工劳动保护特别规定》', '第十二条', '劳动', NULL, NULL, NULL, NULL, '第十二条　县级以上人民政府人力资源社会保障行政部门、安全生产监督管理部门按照各自职责负责对用人单位遵守本规定的情况进行监督检查。 　　工会、妇女组织依法对用人单位遵守本规定的情况进行监督。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10813, '《女职工劳动保护特别规定》', '第十三条', '劳动', NULL, NULL, NULL, NULL, '第十三条　用人单位违反本规定第六条第二款、第七条、第九条第一款规定的，由县级以上人民政府人力资源社会保障行政部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。 　　用人单位违反本规定附录第一条、第二条规定的，由县级以上人民政府安全生产监督管理部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。用人单位违反本规定附录第三条、第四条规定的，由县级以上人民政府安全生产监督管理部门责令限期治理，处5万元以上30万元以下的罚款；情节严重的，责令停止有关作业，或者提请有关人民政府按照国务院规定的权限责令关闭。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10814, '《女职工劳动保护特别规定》', '第十四条', '劳动', NULL, NULL, NULL, NULL, '第十四条　用人单位违反本规定，侵害女职工合法权益的，女职工可以依法投诉、举报、申诉，依法向劳动人事争议调解仲裁机构申请调解仲裁，对仲裁裁决不服的，依法向人民法院提起诉讼。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10815, '《女职工劳动保护特别规定》', '第十五条', '劳动', NULL, NULL, NULL, NULL, '第十五条　用人单位违反本规定，侵害女职工合法权益，造成女职工损害的，依法给予赔偿；用人单位及其直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, title, version_info, chapter_info, section_info, content, deleted) VALUES (10816, '《女职工劳动保护特别规定》', '第十六条', '劳动', NULL, NULL, NULL, NULL, '第十六条　本规定自公布之日起施行。1988年7月21日国务院发布的《女职工劳动保护规定》同时废止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
